import {
  createCheckIcon,
  createCopyIcon,
  createTrashIcon,
  createWarningIcon,
} from "../../webview/icons";
import type { WebLogLine } from "./webHostAdapter";

export type RevealEditorLine = (lineNumber: number) => void;

const kCopyFeedbackDurationMilliseconds = 1500;

export function wireLogPanel(
  body: HTMLElement,
  clearButton: HTMLElement,
  revealEditorLine: RevealEditorLine,
  copyButton?: HTMLElement,
): (line: WebLogLine) => void {
  clearButton.replaceChildren(createTrashIcon());
  clearButton.addEventListener("click", () => {
    body.replaceChildren();
  });

  if (copyButton !== undefined) {
    copyButton.replaceChildren(createCopyIcon());
    let copyFeedbackTimer: ReturnType<typeof setTimeout> | undefined;

    copyButton.addEventListener("click", () => {
      const lines: string[] = [];
      for (const child of Array.from(body.children)) {
        if (child.textContent !== null) {
          lines.push(child.textContent);
        }
      }
      const fullText = lines.join("\n");

      void (async () => {
        let success = false;
        try {
          if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
            await navigator.clipboard.writeText(fullText);
            success = true;
          }
        } catch {
          success = false;
        }

        if (copyFeedbackTimer !== undefined) {
          clearTimeout(copyFeedbackTimer);
        }
        copyButton.replaceChildren(success ? createCheckIcon() : createWarningIcon());
        copyFeedbackTimer = setTimeout(() => {
          copyButton.replaceChildren(createCopyIcon());
          copyFeedbackTimer = undefined;
        }, kCopyFeedbackDurationMilliseconds);
      })();
    });
  }

  return (line) => {
    const hasSourceLocation =
      line.level === "error" &&
      line.lineNumber !== undefined &&
      Number.isInteger(line.lineNumber) &&
      line.lineNumber > 0;
    const lineElement = document.createElement(hasSourceLocation ? "button" : "div");
    lineElement.className =
      line.level === "log" ? "log-panel-line" : `log-panel-line log-${line.level}`;
    lineElement.textContent = line.text;

    if (hasSourceLocation) {
      const lineNumber = line.lineNumber as number;
      lineElement.classList.add("log-panel-source-link");
      lineElement.setAttribute("type", "button");
      lineElement.setAttribute("title", `Go to line ${lineNumber}`);
      lineElement.addEventListener("click", () => {
        revealEditorLine(lineNumber);
      });
    }

    body.appendChild(lineElement);
    body.scrollTop = body.scrollHeight;
  };
}
