// Converts a dropped SVG file into the mt.svg_path(...) snippet a script can
// use as a declared glyph.
//
// Scope is deliberately narrow: <path> elements only, with no transform
// resolution and no arc conversion. Illustrator, Figma and similar exporters
// collapse shapes into <path> and bake transforms into the coordinates, so that
// covers ordinary icon artwork. Anything outside it is reported as a warning
// rather than silently mis-imported, because a wrong shape that still parses is
// harder to notice than one that never appears.

export interface SvgImportResult {
  // Concatenated `d` data, one contour per source <path>, ready to paste into
  // mt.svg_path. Contour order and direction are preserved exactly: the
  // non-zero fill rule needs them to decide which contours are holes.
  pathData: string;
  viewBox: [number, number, number, number];
  pathCount: number;
  // Non-fatal problems: the snippet is still produced, but it may not match the
  // original artwork.
  warnings: string[];
}

export interface SvgImportFailure {
  error: string;
}

// A `d` attribute in either quote style. Kept deliberately simple rather than
// going through DOMParser: the web build already avoids DOM dependencies in
// core/, and this runs on files the user picked, not on hostile input.
const kPathElementPattern = /<path\b[^>]*?\bd\s*=\s*("([^"]*)"|'([^']*)')/gis;
const kViewBoxPattern = /\bviewBox\s*=\s*("([^"]*)"|'([^']*)')/is;
const kWidthPattern = /<svg\b[^>]*?\bwidth\s*=\s*("([^"]*)"|'([^']*)')/is;
const kHeightPattern = /<svg\b[^>]*?\bheight\s*=\s*("([^"]*)"|'([^']*)')/is;
const kTransformPattern = /<(path|g)\b[^>]*?\btransform\s*=/is;
const kArcCommandPattern = /[Aa]/;
const kNonPathShapePattern = /<(circle|ellipse|rect|polygon|polyline|line)\b/gi;

function matchedQuotedValue(match: RegExpMatchArray | null): string | undefined {
  if (match === null) {
    return undefined;
  }
  return match[2] ?? match[3];
}

// Strips the unit suffix Illustrator writes on width/height ("512px").
function parseLength(text: string | undefined): number | undefined {
  if (text === undefined) {
    return undefined;
  }
  const value = Number.parseFloat(text);
  return Number.isFinite(value) && value > 0 ? value : undefined;
}

function parseViewBox(svgText: string): [number, number, number, number] | undefined {
  const raw = matchedQuotedValue(svgText.match(kViewBoxPattern));
  if (raw === undefined) {
    return undefined;
  }
  const numbers = raw
    .split(/[\s,]+/)
    .filter((token) => token.length > 0)
    .map((token) => Number.parseFloat(token));
  if (numbers.length !== 4 || numbers.some((value) => !Number.isFinite(value))) {
    return undefined;
  }
  if (numbers[2] <= 0 || numbers[3] <= 0) {
    return undefined;
  }
  return [numbers[0], numbers[1], numbers[2], numbers[3]];
}

// Collapses the whitespace an exporter leaves between commands so the emitted
// snippet stays readable, while keeping one contour per line.
function tidyPathData(data: string): string {
  return data.replace(/\s+/g, " ").trim();
}

export function convertSvgToDrawingPath(svgText: string): SvgImportResult | SvgImportFailure {
  if (!/<svg\b/i.test(svgText)) {
    return { error: "not an SVG file" };
  }

  const contours: string[] = [];
  kPathElementPattern.lastIndex = 0;
  for (
    let match = kPathElementPattern.exec(svgText);
    match !== null;
    match = kPathElementPattern.exec(svgText)
  ) {
    const data = tidyPathData(matchedQuotedValue(match) ?? "");
    if (data.length > 0) {
      contours.push(data);
    }
  }
  if (contours.length === 0) {
    return { error: "the SVG has no <path> elements to import" };
  }

  const warnings: string[] = [];

  let viewBox = parseViewBox(svgText);
  if (viewBox === undefined) {
    const width = parseLength(matchedQuotedValue(svgText.match(kWidthPattern)));
    const height = parseLength(matchedQuotedValue(svgText.match(kHeightPattern)));
    if (width !== undefined && height !== undefined) {
      viewBox = [0, 0, width, height];
      warnings.push("no viewBox: using the svg width and height instead");
    } else {
      // Better a wrong box the user can correct than a refusal to import.
      viewBox = [0, 0, 512, 512];
      warnings.push("no viewBox, width or height: assuming 0 0 512 512");
    }
  }

  const pathData = contours.join("\n");
  if (kArcCommandPattern.test(pathData)) {
    warnings.push("arc commands (A/a) are not supported by mt.svg_path and will fail to parse");
  }
  if (kTransformPattern.test(svgText)) {
    warnings.push("transform attributes are ignored, so shapes may be offset or scaled wrongly");
  }

  kNonPathShapePattern.lastIndex = 0;
  const shapeNames = new Set<string>();
  for (
    let match = kNonPathShapePattern.exec(svgText);
    match !== null;
    match = kNonPathShapePattern.exec(svgText)
  ) {
    shapeNames.add(match[1].toLowerCase());
  }
  if (shapeNames.size > 0) {
    const names = [...shapeNames].sort().join(", ");
    warnings.push(`only <path> is imported; skipped ${names}`);
  }

  return { pathData, viewBox, pathCount: contours.length, warnings };
}

export function isSvgImportFailure(
  result: SvgImportResult | SvgImportFailure,
): result is SvgImportFailure {
  return "error" in result;
}

// Emits the snippet inserted into the script. The variable name is mechanical
// on purpose: file names are often non-ASCII, and a predictable name is easier
// to rename than a mangled transliteration.
export function formatDrawingPathSnippet(
  result: SvgImportResult,
  variableName: string,
): string {
  const [minX, minY, width, height] = result.viewBox;
  const warningLines = result.warnings.map((warning) => `-- NOTE: ${warning}\n`).join("");
  return (
    `${warningLines}local ${variableName} = mt.svg_path([[\n` +
    `${result.pathData}\n` +
    `]], {\n` +
    `    view_box = { ${minX}, ${minY}, ${width}, ${height} },\n` +
    `    em_scale = 0.7,\n` +
    `})\n`
  );
}

// 1-based line the snippet should be inserted after: past the header comment
// block and any existing file-scope locals, but before the first callback.
// Landing above the callbacks matters because mt.svg_path compiles its template
// once at load time; inside OnLayout it would recompile every frame.
export function findTopLevelInsertLine(scriptSource: string): number {
  const lines = scriptSource.split("\n");
  // Every line before the first callback counts, whatever it holds: header
  // comments, locals, and the continuation lines of a multi-line local (a path
  // string, a table) are all file scope. Only the callback ends the region.
  let lastTopLevel = 0;
  for (const [index, line] of lines.entries()) {
    if (/^\s*function\s+On[A-Za-z]/.test(line)) {
      break;
    }
    lastTopLevel = index + 1;
  }
  // Trailing blank lines are not a useful anchor; back up to real content.
  while (lastTopLevel > 0 && lines[lastTopLevel - 1].trim() === "") {
    lastTopLevel -= 1;
  }
  return lastTopLevel;
}

// Picks a name that does not collide with a local already defined in the
// script, so importing several files in a row just counts up.
export function chooseVariableName(scriptSource: string): string {
  const base = "importedPath";
  if (!new RegExp(`\\blocal\\s+${base}\\b`).test(scriptSource)) {
    return base;
  }
  for (let suffix = 2; suffix < 1000; suffix += 1) {
    const candidate = `${base}${suffix}`;
    if (!new RegExp(`\\blocal\\s+${candidate}\\b`).test(scriptSource)) {
      return candidate;
    }
  }
  return `${base}${Date.now()}`;
}
