// Lua chunks executed inside the wasmoon state to set up the simulator's
// engine internals. This mirrors what the host plugin does natively (sol2 /
// lua_sethook): ctx proxies with per-hook write whitelists, instruction
// budget, per-hook seeded math.randomseed, and global-write detection. The
// Lua-visible behavior defined here is the contract user scripts run against,
// so any change must be applied to the C++ host bindings as well.

// Loaded FIRST, before the prelude and before sandboxing, so it can capture
// debug.sethook while the debug library still exists.
import {
  cameraMembers,
  boundingBoxMembers,
  characterGeometryMembers,
  characterMembers,
  colorMembers,
  globalMembers,
  globalFillMembers,
  gradientMembers,
  textureMembers,
  blurMembers,
  globalStrokeMembers,
  globalShadowMembers,
  globalEmojiMembers,
  individualFillMembers,
  individualStrokeMembers,
  individualShadowMembers,
  LuaApiMember,
  partGeometryMembers,
  partMembers,
  shapeMembers,
  shapeCameraMembers,
  outputMembers,
  writableMembers,
} from "../shared/scriptingApi";

// The most cameras for shapes a script may declare; the host holds the same limit.
export const kMaxShapeCameras = 16;


function runtimeFieldType(member: LuaApiMember): string {
  let result: string;
  switch (member.type) {
    case "number":
    case "integer":
      result = "number";
      break;
    case "boolean":
    case "string":
    case "function":
      result = member.type;
      break;
    case "MtColor":
      result = "color";
      break;
    case "MtGlobalFill":
      result = "global_fill";
      break;
    case "MtGradient":
      result = "gradient";
      break;
    case "MtTexture":
      result = "texture";
      break;
    case "MtBlur":
      result = "blur";
      break;
    case "MtGlobalStroke":
      result = "global_stroke";
      break;
    case "MtGlobalShadow":
      result = "global_shadow";
      break;
    case "MtGlobalEmoji":
      result = "global_emoji";
      break;
    case "MtIndividualFill":
      result = "individual_fill";
      break;
    case "MtIndividualStroke":
      result = "individual_stroke";
      break;
    case "MtIndividualShadow":
      result = "individual_shadow";
      break;
    case "MtCharacterGeometry":
      result = "character_geometry";
      break;
    case "MtPartGeometry":
      result = "part_geometry";
      break;
    case "number[]":
      result = "number_array";
      break;
    case "MtDrawingPath":
      // Read only: a script edits the path in place and the shape view serves it.
      result = "path";
      break;
    default:
      throw new Error(`No Lua runtime validator for field type '${member.type}'`);
  }
  return result;
}

function makeLuaFieldSchema(members: readonly LuaApiMember[]): string {
  return members.map((member) => `    ${member.name} = "${runtimeFieldType(member)}",`).join("\n");
}

// Mirrors ScriptApiFields::clampToRange on the host (src/scripting/ScriptBindings.cc):
// a script-written number below its schema "min" is clamped up rather than
// rejected or passed through as-is. Only fields with a configured min are
// listed here; every other field is left unclamped.
function makeLuaFieldMinSchema(members: readonly LuaApiMember[]): string {
  return members
    .filter((member) => member.min !== undefined)
    .map((member) => `    ${member.name} = ${member.min},`)
    .join("\n");
}

// Same as makeLuaFieldMinSchema, but for a script-written number above its
// schema "max" (clamped down). Only fields with a configured max are listed.
function makeLuaFieldMaxSchema(members: readonly LuaApiMember[]): string {
  return members
    .filter((member) => member.max !== undefined)
    .map((member) => `    ${member.name} = ${member.max},`)
    .join("\n");
}

