import { flattenPath, type FlattenedSubpath } from "./parts";

// Enough for every distinct path of a frame of text to stay resident between frames, so a camera that only moves
// never flattens a path again.
export const kFlattenCacheCapacity = 2048;

interface FlattenedEntry {
  curveSegments: number;
  subpaths: readonly FlattenedSubpath[];
}

// In order of last use, the oldest first.
const flattened = new Map<string, FlattenedEntry>();

// The flattened outline of a path, shared by everything that projects the same path at the same curve segment count.
// The result is shared, so it must not be changed. The least recently used path is dropped past the capacity, so
// paths that change every frame cannot make it grow.
export function flattenPathCached(pathData: string, curveSegments: number): readonly FlattenedSubpath[] {
  let entry = flattened.get(pathData);
  if (entry === undefined || entry.curveSegments !== curveSegments) {
    entry = { curveSegments, subpaths: flattenPath(pathData, curveSegments) };
  }
  flattened.delete(pathData);
  flattened.set(pathData, entry);
  if (flattened.size > kFlattenCacheCapacity) {
    const oldest = flattened.keys().next();
    if (!oldest.done) {
      flattened.delete(oldest.value);
    }
  }
  return entry.subpaths;
}

export function flattenCacheSize(): number {
  return flattened.size;
}

export function clearFlattenCache(): void {
  flattened.clear();
}
