import { createLiveSamplePreview } from "./sampleLivePreview";
import type { SamplePreviewCanvasFactory } from "./samplePreviewCanvas";
import { SamplePreviewPlayer } from "./samplePreviewPlayer";
import type { SamplePreviewRuntimeFactory } from "./samplePreviewRuntime";
import { getLocale, onLocaleChange, t } from "../../shared/i18n";
import { localizedSampleDescription } from "../../shared/sampleDescriptions.mjs";
import { kSampleGenres, sampleGenrePath, type SampleGenre } from "../../shared/sampleGenres";
import { formatSampleCardDescription, sampleMatchesQuery, type SampleEntry } from "./sampleCatalog";

export function sampleMatchesBrowserQuery(sample: SampleEntry, query: string): boolean {
  const genreWords = sampleGenrePath(sample.id).flatMap((genre) => Object.values(genre.labels)).join(" ");
  const code = (sample.source ?? "").replace(/--\[\[[\s\S]*?\]\]/g, "").replace(/--.*$/gm, "");
  const apiWords = [...code.matchAll(/\b(?:mt|ctx)(?:[.:][A-Za-z_]\w*)+/g)].map((match) => match[0]).join(" ");
  return query.toLowerCase().trim().split(/\s+/).every((word) =>
    sampleMatchesQuery(sample, word) || `${genreWords} ${apiWords}`.toLowerCase().includes(word));
}

export function sampleBelongsToGenre(sample: SampleEntry, genreId: string): boolean {
  return genreId === "all" || sample.category === genreId ||
    sampleGenrePath(sample.id).some((genre) => genre.id === genreId) ||
    (genreId === `${sample.category}/other` && sampleGenrePath(sample.id).length === 0);
}

function stopSampleVideos(container: HTMLElement, playingVideo?: HTMLVideoElement): void {
  for (const video of container.querySelectorAll("video")) {
    if (video !== playingVideo) video.pause();
  }
}

function createSamplePreview(
  sample: SampleEntry,
  observer: IntersectionObserver,
  stopVideos: (playingVideo?: HTMLVideoElement) => void,
  autoplay: boolean,
): HTMLElement | undefined {
  let preview: HTMLElement | undefined;
  if (sample.thumbnailUrl !== undefined) {
    const container = document.createElement("span");
    container.className = "sample-card-preview";

    const thumbnail = document.createElement("img");
    thumbnail.className = "sample-card-thumbnail";
    thumbnail.alt = "";
    thumbnail.loading = "lazy";
    thumbnail.dataset.thumbnailUrl = sample.thumbnailUrl;
    container.appendChild(thumbnail);
    observer.observe(thumbnail);

    if (sample.videoUrl !== undefined) {
      const playButton = document.createElement("button");
      playButton.type = "button";
      playButton.className = "sample-card-play";
      playButton.setAttribute("aria-label", t("samples.play"));
      playButton.textContent = "▶";
      const videoUrl = sample.videoUrl;
      playButton.addEventListener("click", () => {
        stopVideos();
        playSamplePreview(container, videoUrl, stopVideos);
      });
      container.appendChild(playButton);
      if (autoplay) {
        stopVideos();
        playSamplePreview(container, videoUrl, stopVideos);
      }
    }
    preview = container;
  }
  return preview;
}

function playSamplePreview(
  container: HTMLElement,
  videoUrl: string,
  stopVideos: (playingVideo?: HTMLVideoElement) => void,
): void {
  const video = document.createElement("video");
  video.className = "sample-card-video";
  video.src = videoUrl;
  video.controls = true;
  video.autoplay = true;
  video.loop = true;
  video.muted = true;
  video.playsInline = true;
  video.addEventListener("play", () => stopVideos(video));
  container.replaceChildren(video);
}

function createThumbnailObserver(grid: HTMLElement): IntersectionObserver {
  return new IntersectionObserver(
    (observedEntries, self) => {
      for (const observed of observedEntries) {
        const thumbnail = observed.target as HTMLImageElement;
        const thumbnailUrl = thumbnail.dataset.thumbnailUrl;
        if (observed.isIntersecting && thumbnailUrl !== undefined) {
          thumbnail.src = thumbnailUrl;
          self.unobserve(thumbnail);
        }
      }
    },
    // Visibility is relative to the independently scrolling result list.
    { root: grid, rootMargin: "200px" },
  );
}

export interface SampleBrowserElements {
  tree: HTMLElement;
  grid: HTMLElement;
  search: HTMLInputElement;
}

export interface SampleBrowserPreviewOptions {
  createRuntime: SamplePreviewRuntimeFactory;
  createCanvas?: SamplePreviewCanvasFactory;
  allowAutoplay?: () => boolean;
}

export function createSampleBrowser(
  elements: SampleBrowserElements,
  initialSamples: readonly SampleEntry[],
  openSample: (sample: SampleEntry) => Promise<boolean>,
  previewOptions?: SampleBrowserPreviewOptions,
): { updateSamples: (samples: readonly SampleEntry[]) => void; refresh: () => void; stop: () => void; dispose: () => void } {
  let samples = initialSamples;
  let activeGenre = "all";
  let selectedSampleId: string | undefined;
  const expandedGenres = new Set<string>(["reference", "showcase", "showcase/basic"]);
  let observer = createThumbnailObserver(elements.grid);
  let opening = false;
  let disposed = false;
  const previewPlayer = previewOptions === undefined ? undefined : new SamplePreviewPlayer(previewOptions.createRuntime);
  let previewDisposers: (() => void)[] = [];

  function stopPreviews(): void {
    previewPlayer?.stop();
    stopSampleVideos(elements.grid);
  }

  function button(label: string, action: () => void): HTMLButtonElement {
    const element = document.createElement("button");
    element.type = "button";
    element.textContent = label;
    element.dataset.browserFocus = label;
    element.addEventListener("click", action);
    return element;
  }

  function selectGenre(genreId: string): void {
    activeGenre = genreId;
    selectedSampleId = undefined;
    render();
  }

  function selectSample(sampleId: string): void {
    selectedSampleId = sampleId;
    render();
  }

  function renderTree(matches: readonly SampleEntry[], searching: boolean): void {
    elements.tree.replaceChildren();
    elements.tree.setAttribute("aria-label", t("samples.navigation"));
    const allButton = button(`${t("samples.all")} (${matches.length})`, () => selectGenre("all"));
    allButton.className = "sample-tree-select";
    allButton.setAttribute("aria-current", String(activeGenre === "all" && selectedSampleId === undefined));
    elements.tree.appendChild(allButton);

    function appendGenre(parent: HTMLElement, genre: SampleGenre): void {
      const entries = matches.filter((sample) => sampleBelongsToGenre(sample, genre.id));
      if (entries.length === 0) return;
      const branch = document.createElement("details");
      branch.open = searching || expandedGenres.has(genre.id);
      branch.dataset.genreId = genre.id;
      branch.addEventListener("toggle", () => {
        if (!searching && branch.isConnected) {
          if (branch.open) expandedGenres.add(genre.id);
          else expandedGenres.delete(genre.id);
        }
      });
      const summary = document.createElement("summary");
      const choose = button(`${genre.labels[getLocale()]} (${entries.length})`, () => {
        expandedGenres.add(genre.id);
        selectGenre(genre.id);
      });
      choose.className = "sample-tree-select";
      choose.setAttribute("aria-current", String(activeGenre === genre.id && selectedSampleId === undefined));
      choose.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
      });
      summary.appendChild(choose);
      branch.appendChild(summary);
      const children = document.createElement("div");
      children.className = "sample-tree-children";
      if (genre.children !== undefined) {
        for (const child of genre.children) appendGenre(children, child);
        const unclassified = entries.filter((sample) => sampleGenrePath(sample.id).length === 0);
        if (unclassified.length > 0) {
          appendGenre(children, { id: `${genre.id}/other`, labels: { en: "Other", ja: "その他" } });
        }
      } else {
        for (const sample of entries) {
          const leaf = button([sample.animationId, sample.title || sample.name].filter(Boolean).join(" · "), () => selectSample(sample.id));
          leaf.className = "sample-tree-select sample-tree-leaf";
          leaf.dataset.sampleId = sample.id;
          leaf.setAttribute("aria-current", String(selectedSampleId === sample.id));
          children.appendChild(leaf);
        }
      }
      branch.appendChild(children);
      parent.appendChild(branch);
    }

    for (const genre of kSampleGenres) appendGenre(elements.tree, genre);
    for (const category of new Set(matches.map((sample) => sample.category))) {
      if (!kSampleGenres.some((genre) => genre.id === category)) {
        appendGenre(elements.tree, { id: category, labels: { en: category, ja: category } });
      }
    }
  }

  function createCard(sample: SampleEntry, detail: boolean, wantsAutoplay: boolean): HTMLElement {
    const autoplay = wantsAutoplay && (previewOptions?.allowAutoplay?.() ?? true);
    const card = document.createElement("article");
    card.className = detail ? "sample-card sample-detail" : "sample-card";
    card.dataset.sampleId = sample.id;
    if (previewPlayer !== undefined && (sample.category === "reference" || sample.category === "showcase")) {
      const preview = createLiveSamplePreview(sample, previewPlayer, observer, previewOptions?.createCanvas,
        () => stopSampleVideos(elements.grid));
      previewDisposers.push(preview.dispose);
      card.appendChild(preview.element);
      if (autoplay) preview.play();
    } else {
      const preview = createSamplePreview(sample, observer, (playingVideo) => {
        previewPlayer?.stop();
        stopSampleVideos(elements.grid, playingVideo);
      }, autoplay);
      if (preview !== undefined) card.appendChild(preview);
    }
    const path = sampleGenrePath(sample.id);
    const location = document.createElement("span");
    location.className = "sample-card-category";
    location.textContent = path.length > 0 ? path.map((genre) => genre.labels[getLocale()]).join(" / ")
      : kSampleGenres.find((genre) => genre.id === sample.category)?.labels[getLocale()] ?? sample.category;
    card.appendChild(location);
    const name = button([sample.animationId, sample.title || sample.name].filter(Boolean).join(" · "), () => selectSample(sample.id));
    name.className = "sample-card-name";
    card.appendChild(name);
    const description = document.createElement("p");
    description.className = "sample-card-description";
    const localizedDescription = localizedSampleDescription(sample, getLocale());
    description.textContent = detail ? localizedDescription : formatSampleCardDescription(localizedDescription);
    card.appendChild(description);
    const metadata = document.createElement("span");
    metadata.className = "sample-card-meta";
    metadata.textContent = [sample.author, sample.version ? `v${sample.version}` : "",
      sample.apiLevel === undefined ? "" : `API ${sample.apiLevel}`].filter(Boolean).join(" · ");
    card.appendChild(metadata);
    if (detail) {
      const fileName = document.createElement("code");
      fileName.textContent = sample.id;
      card.appendChild(fileName);
    }
    const open = button(t("samples.open"), () => {
      if (!opening) {
        opening = true;
        open.disabled = true;
        card.classList.remove("sample-card-failed");
        const errorMessage = card.querySelector(".sample-card-error");
        errorMessage?.remove();
        void openSample(sample).catch((error: unknown) => {
          console.warn(`failed to open sample ${sample.id}: ${String(error)}`);
          if (!disposed) {
            card.classList.add("sample-card-failed");
            const message = document.createElement("span");
            message.className = "sample-card-error";
            message.setAttribute("role", "alert");
            message.textContent = t("samples.openFailed");
            card.appendChild(message);
          }
        }).finally(() => {
          opening = false;
          open.disabled = false;
        });
      }
    });
    open.className = "sample-card-open";
    card.appendChild(open);
    if (sample.sourceUrl !== undefined) {
      const link = document.createElement("a");
      link.className = "sample-card-source";
      link.href = sample.sourceUrl;
      link.target = "_blank";
      link.rel = "noopener noreferrer";
      link.textContent = t("samples.viewSubmission");
      card.appendChild(link);
    }
    return card;
  }

  function render(): void {
    const focusKey = (document.activeElement as HTMLElement | null)?.dataset.browserFocus;
    const searching = elements.search.value.trim() !== "";
    const matches = samples.filter((sample) => sampleMatchesBrowserQuery(sample, elements.search.value));
    const selected = matches.find((sample) => sample.id === selectedSampleId);
    if (selected === undefined) selectedSampleId = undefined;
    stopPreviews();
    for (const dispose of previewDisposers) dispose();
    previewDisposers = [];
    observer.disconnect();
    observer = createThumbnailObserver(elements.grid);
    renderTree(matches, searching);
    elements.search.placeholder = t("samples.search");
    elements.search.setAttribute("aria-label", t("samples.search"));
    elements.grid.replaceChildren();
    if (selected !== undefined) {
      const back = button(t("samples.back"), () => { selectedSampleId = undefined; render(); });
      back.className = "sample-browser-list-header";
      elements.grid.appendChild(back);
      elements.grid.appendChild(createCard(selected, true, true));
    } else {
      const visible = matches.filter((sample) => searching || sampleBelongsToGenre(sample, activeGenre));
      const heading = document.createElement("div");
      heading.className = "sample-browser-list-header";
      heading.setAttribute("role", "status");
      heading.textContent = `${searching ? t("samples.results") : genreLabel(activeGenre)} (${visible.length})`;
      elements.grid.appendChild(heading);
      if (visible.length === 0) {
        const empty = document.createElement("div");
        empty.className = "sample-browser-empty";
        empty.textContent = t("samples.noMatch");
        elements.grid.appendChild(empty);
      }
      const ordered = kSampleGenres.flatMap(collectSampleIds);
      const order = new Map(ordered.map((sampleId, index) => [sampleId, index]));
      visible.sort((first, second) => (order.get(first.id) ?? ordered.length) - (order.get(second.id) ?? ordered.length));
      for (const sample of visible) elements.grid.appendChild(createCard(sample, false, visible.length === 1));
    }
    if (focusKey !== undefined) {
      const focusTarget = [...elements.tree.querySelectorAll<HTMLElement>("[data-browser-focus]"),
        ...elements.grid.querySelectorAll<HTMLElement>("[data-browser-focus]")]
        .find((element) => element.dataset.browserFocus === focusKey);
      focusTarget?.focus();
    }
  }

  function collectSampleIds(genre: SampleGenre): string[] {
    return [...(genre.sampleIds ?? []), ...(genre.children ?? []).flatMap(collectSampleIds)];
  }

  function genreLabel(genreId: string): string {
    function find(genres: readonly SampleGenre[]): SampleGenre | undefined {
      let result = genres.find((genre) => genre.id === genreId);
      for (const genre of genres) result ??= find(genre.children ?? []);
      return result;
    }
    return genreId === "all" ? t("samples.all") : find(kSampleGenres)?.labels[getLocale()] ?? (genreId.endsWith("/other") ? t("samples.other") : genreId);
  }

  const unsubscribe = onLocaleChange(render);
  elements.search.addEventListener("input", render);
  render();
  return {
    updateSamples: (updated) => { samples = updated; render(); },
    refresh: render,
    stop: stopPreviews,
    dispose: () => {
      disposed = true;
      unsubscribe();
      elements.search.removeEventListener("input", render);
      stopPreviews();
      for (const dispose of previewDisposers) dispose();
      previewDisposers = [];
      observer.disconnect();
    },
  };
}
