import type { LuaHookPhase } from "./scriptingApi";

export interface LuaHookInfo {
  name: string;
  phase: LuaHookPhase;
  /** Full function signature line for hover / detail. */
  signature: string;
  description: string;
  descriptionJa?: string;
  /** Body snippet inserted after `function Name(ctx)\n`. */
  bodyComment: string;
}

/**
 * Host-invoked global entry points. Names are PascalCase so typical LuaLS
 * lowercase-global diagnostics do not fire on the definitions.
 */
export const kLuaHooks: readonly LuaHookInfo[] = [
  {
    name: "OnInitialize",
    phase: "initialize",
    signature: "function OnInitialize(ctx)",
    description:
      "Compatibility hook for existing scripts; do not use it in new scripts. " +
      "Initialize constants in locals declared outside functions instead.",
    descriptionJa:
      "既存スクリプトとの互換性のためのコールバックです。新規スクリプトでは使用せず、" +
      "初期化処理と定数には関数の外側で宣言した local 変数を使用してください。",
    bodyComment: "-- Compatibility hook for existing scripts.",
  },
  {
    name: "OnPreLayout",
    phase: "pre_layout",
    signature: "function OnPreLayout(ctx)",
    description:
      "Called every frame before layout generation. " +
      "Read and write `ctx.global` and `ctx.camera`, or declare custom glyphs (`ctx.glyphs:declare`), shapes (`ctx.shapes:declare`), and shape cameras (`ctx.shape_cameras:declare`). " +
      "`ctx.char_count`, `ctx.part_count`, and `ctx.shape_count` are not defined yet; read and rewrite text via `ctx.global.text`.",
    descriptionJa:
      "レイアウト生成前（毎フレーム）に呼ばれます。" +
      "`ctx.global` および `ctx.camera` の全体設定を読み書きしたり、カスタムグリフ（`ctx.glyphs:declare`）・図形（`ctx.shapes:declare`）・図形カメラ（`ctx.shape_cameras:declare`）を宣言したりします。" +
      "`ctx.char_count`・`ctx.part_count`・`ctx.shape_count` はまだ未定義です（テキスト変更は `ctx.global.text` へ代入）。",
    bodyComment: "-- Adjust ctx.global / ctx.camera before layout.",
  },
  {
    name: "OnLayout",
    phase: "layout",
    signature: "function OnLayout(ctx)",
    description:
      "Called every frame after layout generation. " +
      "Adjust per-character (`ctx.chars`), per-part (`ctx.parts`), shape (`ctx.shapes`), shape camera (`ctx.shape_cameras`), `ctx.bounding_box`, and `ctx.output` values. " +
      "`ctx.global` and `ctx.camera` are read-only finalized values, and `ctx.char_count`, `ctx.part_count`, `ctx.shape_count`, and `ctx.font` are defined.",
    descriptionJa:
      "レイアウト生成後（毎フレーム）に呼ばれます。" +
      "生成された文字（`ctx.chars`）・パーツ（`ctx.parts`）・図形（`ctx.shapes`）・図形カメラ（`ctx.shape_cameras`）・`ctx.bounding_box`・`ctx.output` を個別に調整します。" +
      "`ctx.global` / `ctx.camera` は確定値（読み取り専用）として参照でき、文字数・パーツ数・図形数や `ctx.font` も利用できます。",
    bodyComment: "-- Adjust ctx.chars / ctx.parts after layout.",
  },
  {
    name: "OnPath",
    phase: "path",
    signature: "function OnPath(ctx)",
    description:
      "Called every frame after OnLayout. Lazily select only the outlines you need through `ctx.paths` (`:part`, `:character`, `:shape`, `:select`). " +
      "Edit or replace each selected part's normalized drawing path before rendering.",
    descriptionJa:
      "OnLayout の後に毎フレーム呼ばれ、`ctx.paths`（`:part`・`:character`・`:shape`・`:select`）から必要なパーツや図形の輪郭を遅延取得します。" +
      "取得したパーツの正規化描画パスを編集・差し替えてから描画へ渡せます。",
    bodyComment: "-- Select and replace normalized outlines through ctx.paths.",
  },
];

export function findLuaHook(name: string): LuaHookInfo | undefined {
  return kLuaHooks.find((hook) => hook.name === name);
}

export function getLuaHookDescription(hook: LuaHookInfo, isJapanese: boolean): string {
  const description = isJapanese && hook.descriptionJa !== undefined ? hook.descriptionJa : hook.description;
  return description;
}
