type NumberKey<T> = {
  [Key in keyof T]-?: T[Key] extends number ? Key : never;
}[keyof T];

type StringKey<T> = {
  [Key in keyof T]-?: T[Key] extends string ? Key : never;
}[keyof T];

type BooleanKey<T> = {
  [Key in keyof T]-?: T[Key] extends boolean ? Key : never;
}[keyof T];

type ColorKey<T> = {
  [Key in keyof T]-?: T[Key] extends Rgba ? Key : never;
}[keyof T];

interface InspectorFieldBase {
  label: string;
  labelFor?: (scene: Scene) => string;
  // Stable scene-model path used by coverage tests and future migrations.
  path: string;
  enabled?: (scene: Scene) => boolean;
  // A field the current scene gives no meaning is left out of the inspector, as the plugin hides it.
  visible?: (scene: Scene) => boolean;
}

export interface NumberInspectorField extends InspectorFieldBase {
  kind: "number";
  step: number;
  read: (scene: Scene) => number;
  write: (scene: Scene, value: number) => void;
}

export interface TextInspectorField extends InspectorFieldBase {
  kind: "text";
  multiline: boolean;
  read: (scene: Scene) => string;
  write: (scene: Scene, value: string) => void;
}

export interface BooleanInspectorField extends InspectorFieldBase {
  kind: "boolean";
  read: (scene: Scene) => boolean;
  write: (scene: Scene, value: boolean) => void;
}

export interface SelectInspectorField extends InspectorFieldBase {
  kind: "select";
  options: ReadonlyArray<readonly [value: string, label: string]>;
  read: (scene: Scene) => string;
  write: (scene: Scene, value: string) => void;
}

export interface FontInspectorField extends InspectorFieldBase {
  kind: "font";
  read: (scene: Scene) => string;
}

export interface ColorInspectorField extends InspectorFieldBase {
  kind: "color";
  showAlpha: boolean;
  read: (scene: Scene) => Rgba;
}

export type InspectorField =
  | NumberInspectorField
  | TextInspectorField
  | BooleanInspectorField
  | SelectInspectorField
  | FontInspectorField
  | ColorInspectorField;

export interface InspectorSection {
  page: InspectorPage;
  title: string;
  initiallyOpen?: boolean;
  fields: InspectorField[];
}

function numberField<T extends object>(
  label: string,
  root: string,
  target: (scene: Scene) => T,
  key: NumberKey<T>,
  normalize: (value: number) => number = (value) => value,
  step = 0.01,
): NumberInspectorField {
  return {
    kind: "number",
    step,
    label,
    path: `${String(root)}.${String(key)}`,
    read: (scene) => target(scene)[key] as number,
    write: (scene, value) => Object.assign(target(scene), { [key]: normalize(value) }),
  };
}

function textField<T extends object>(
  label: string,
  root: string,
  target: (scene: Scene) => T,
  key: StringKey<T>,
  multiline = false,
): TextInspectorField {
  return {
    kind: "text",
    label,
    path: `${String(root)}.${String(key)}`,
    multiline,
    read: (scene) => target(scene)[key] as string,
    write: (scene, value) => Object.assign(target(scene), { [key]: value }),
  };
}

function booleanField<T extends object>(
  label: string,
  root: string,
  target: (scene: Scene) => T,
  key: BooleanKey<T>,
): BooleanInspectorField {
  return {
    kind: "boolean",
    label,
    path: `${String(root)}.${String(key)}`,
    read: (scene) => target(scene)[key] as boolean,
    write: (scene, value) => Object.assign(target(scene), { [key]: value }),
  };
}

function selectField<T extends object>(
  label: string,
  root: string,
  target: (scene: Scene) => T,
  key: StringKey<T>,
  options: ReadonlyArray<readonly [value: T[StringKey<T>] & string, label: string]>,
): SelectInspectorField {
  return {
    kind: "select",
    label,
    path: `${String(root)}.${String(key)}`,
    options,
    read: (scene) => target(scene)[key] as string,
    write: (scene, value) => Object.assign(target(scene), { [key]: value }),
  };
}

function numberArrayItemField(
  label: string,
  root: string,
  target: (scene: Scene) => number[],
  index: number,
  normalize: (value: number) => number = (value) => value,
): NumberInspectorField {
  return {
    kind: "number",
    step: 0.01,
    label,
    path: `${root}.${index}`,
    read: (scene) => target(scene)[index] ?? 0,
    write: (scene, value) => {
      target(scene)[index] = normalize(value);
    },
  };
}

function textArrayItemField(
  label: string,
  root: string,
  target: (scene: Scene) => string[],
  index: number,
): TextInspectorField {
  return {
    kind: "text",
    label,
    path: `${root}.${index}`,
    multiline: false,
    read: (scene) => target(scene)[index] ?? "",
    write: (scene, value) => {
      target(scene)[index] = value;
    },
  };
}

function booleanArrayItemField(
  label: string,
  root: string,
  target: (scene: Scene) => boolean[],
  index: number,
): BooleanInspectorField {
  return {
    kind: "boolean",
    label,
    path: `${root}.${index}`,
    read: (scene) => target(scene)[index] ?? false,
    write: (scene, value) => {
      target(scene)[index] = value;
    },
  };
}

function colorArrayItemField(
  label: string,
  root: string,
  target: (scene: Scene) => Rgba[],
  index: number,
): ColorInspectorField {
  return {
    kind: "color",
    showAlpha: true,
    label,
    path: `${root}.${index}`,
    read: (scene) => target(scene)[index],
  };
}

function colorField<T extends object>(
  label: string,
  root: string,
  target: (scene: Scene) => T,
  key: ColorKey<T>,
  showAlpha = true,
): ColorInspectorField {
  return {
    kind: "color",
    showAlpha,
    label,
    path: `${String(root)}.${String(key)}`,
    read: (scene) => target(scene)[key] as Rgba,
  };
}

function fontField(label: string): FontInspectorField {
  return {
    kind: "font",
    label,
    path: "global.fontName",
    read: (scene) => scene.global.fontName,
  };
}

function enabledWhen<Field extends InspectorField>(
  field: Field,
  predicate: (scene: Scene) => boolean,
): Field {
  return { ...field, enabled: predicate };
}

