function textureControlField(
  index: 0 | 1 | 2 | 3,
  key: NumberKey<GlobalScene>,
): NumberInspectorField {
  return {
    ...numberField(kTextureControlLabels.none[index], "global", global, key),
    labelFor: (scene: Scene) => kTextureControlLabels[global(scene).textureType][index],
  };
}

function textureFifthControlField(): NumberInspectorField {
  return {
    ...numberField("P5", "global", global, "textureP5"),
    labelFor: (scene: Scene) => kTextureFifthControlLabels[global(scene).textureType] ?? "P5",
    visible: (scene: Scene) => kTextureFifthControlLabels[global(scene).textureType] !== undefined,
  };
}

