import type { EvaluatedFrame } from "../../core/frameEvaluator";
import type { SampleEntry } from "./sampleCatalog";
import type { SamplePreviewRuntime, SamplePreviewRuntimeFactory } from "./samplePreviewRuntime";

export type SamplePreviewState = "loading" | "playing" | "paused" | "stopped" | "error";

export interface SamplePreviewView {
  cycleCompleted?: () => void;
  stateChanged: (state: SamplePreviewState, error?: string) => void;
  render: (frame: EvaluatedFrame, frameNumber: number, durationFrames: number, fps: number) => void;
}

export interface SamplePreviewClock {
  now: () => number;
  request: (callback: (timestamp: number) => void) => number;
  cancel: (handle: number) => void;
}

const kMillisecondsPerSecond = 1000;

export class SamplePreviewPlayer {
  private generation = 0;
  private runtime: SamplePreviewRuntime | undefined;
  private view: SamplePreviewView | undefined;
  private scheduledFrame: number | undefined;
  private state: SamplePreviewState = "stopped";
  private currentFrame = 0;
  private frameOffset = 0;
  private startedAt = 0;
  private completedCycles = 0;

  constructor(
    private readonly createRuntime: SamplePreviewRuntimeFactory,
    private readonly clock: SamplePreviewClock = {
      now: () => performance.now(),
      request: (callback) => requestAnimationFrame(callback),
      cancel: (handle) => cancelAnimationFrame(handle),
    },
  ) {}

  async start(sample: SampleEntry, view: SamplePreviewView): Promise<void> {
    this.stop();
    const generation = this.generation;
    this.view = view;
    this.changeState("loading");
    let runtime: SamplePreviewRuntime | undefined;
    try {
      runtime = await this.createRuntime(sample);
      if (generation !== this.generation) {
        runtime.dispose();
      } else {
        if (!Number.isFinite(runtime.fps) || runtime.fps <= 0 ||
          !Number.isSafeInteger(runtime.durationFrames) || runtime.durationFrames <= 0) {
          throw new Error("Invalid preview timeline");
        }
        this.runtime = runtime;
        this.currentFrame = 0;
        this.renderFrame();
        this.resume();
      }
    } catch (error) {
      if (generation === this.generation) {
        if (this.runtime === undefined) runtime?.dispose();
        this.fail(error);
      }
    }
  }

  pause(): void {
    if (this.state === "playing") {
      this.cancelFrame();
      this.changeState("paused");
    }
  }

  resume(): void {
    if (this.runtime !== undefined && this.state !== "playing") {
      this.frameOffset = this.currentFrame;
      this.startedAt = this.clock.now();
      this.completedCycles = 0;
      this.changeState("playing");
      this.scheduleFrame();
    }
  }

  seek(frame: number): void {
    if (this.runtime !== undefined && Number.isFinite(frame)) {
      this.currentFrame = Math.min(Math.max(Math.round(frame), 0), this.runtime.durationFrames - 1);
      this.frameOffset = this.currentFrame;
      this.startedAt = this.clock.now();
      this.completedCycles = 0;
      try {
        this.renderFrame();
      } catch (error) {
        this.fail(error);
      }
    }
  }

  stop(): void {
    this.generation += 1;
    this.cancelFrame();
    this.runtime?.dispose();
    this.runtime = undefined;
    this.changeState("stopped");
    this.view = undefined;
  }

  private cancelFrame(): void {
    if (this.scheduledFrame !== undefined) this.clock.cancel(this.scheduledFrame);
    this.scheduledFrame = undefined;
  }

  private changeState(state: SamplePreviewState, error?: string): void {
    this.state = state;
    this.view?.stateChanged(state, error);
  }

  private fail(error: unknown): void {
    this.cancelFrame();
    this.runtime?.dispose();
    this.runtime = undefined;
    this.changeState("error", error instanceof Error ? error.message : String(error));
  }

  private renderFrame(): void {
    if (this.runtime !== undefined) {
      this.view?.render(this.runtime.evaluate(this.currentFrame), this.currentFrame,
        this.runtime.durationFrames, this.runtime.fps);
    }
  }

  private scheduleFrame(): void {
    const generation = this.generation;
    this.scheduledFrame = this.clock.request((timestamp) => {
      if (generation === this.generation && this.state === "playing" && this.runtime !== undefined) {
        this.scheduledFrame = undefined;
        const elapsedFrames = Math.floor((timestamp - this.startedAt) * this.runtime.fps / kMillisecondsPerSecond);
        const playbackFrame = this.frameOffset + Math.max(0, elapsedFrames);
        const cycles = Math.floor(playbackFrame / this.runtime.durationFrames);
        const nextFrame = playbackFrame % this.runtime.durationFrames;
        try {
          if (nextFrame !== this.currentFrame) {
            this.currentFrame = nextFrame;
            this.renderFrame();
          }
          if (cycles > this.completedCycles) {
            this.completedCycles = cycles;
            this.view?.cycleCompleted?.();
          }
          if (generation === this.generation && this.state === "playing") this.scheduleFrame();
        } catch (error) {
          this.fail(error);
        }
      }
    });
  }
}
