import { createPlayIcon, createPauseIcon, createFullscreenIcon, createExitFullscreenIcon } from "../../webview/icons";
import { t } from "../../shared/i18n";
import { createSamplePreviewCanvas, type SamplePreviewCanvas, type SamplePreviewCanvasFactory } from "./samplePreviewCanvas";
import type { SampleEntry } from "./sampleCatalog";
import { SamplePreviewPlayer, type SamplePreviewState } from "./samplePreviewPlayer";

export function createLiveSamplePreview(
  sample: SampleEntry,
  player: SamplePreviewPlayer,
  observer: IntersectionObserver,
  createCanvas: SamplePreviewCanvasFactory = createSamplePreviewCanvas,
  beforePlay: () => void = () => {},
): { element: HTMLElement; play: () => void; dispose: () => void } {
  const element = document.createElement("div");
  element.className = "sample-live-preview";
  const viewport = document.createElement("div");
  viewport.className = "sample-live-viewport";
  const canvasContainer = document.createElement("button");
  canvasContainer.type = "button";
  canvasContainer.className = "sample-live-canvas";
  const overlay = document.createElement("div");
  overlay.className = "sample-live-controls-overlay";
  const controls = document.createElement("div");
  controls.className = "sample-live-controls";
  const playButton = document.createElement("button");
  playButton.type = "button";
  const fullscreenButton = document.createElement("button");
  fullscreenButton.type = "button";
  fullscreenButton.className = "sample-live-fullscreen";
  fullscreenButton.hidden = typeof viewport.requestFullscreen !== "function" || document.fullscreenEnabled === false;
  const position = document.createElement("input");
  position.type = "range";
  position.min = "0";
  position.max = "0";
  position.value = "0";
  position.step = "1";
  position.setAttribute("aria-label", t("samples.previewPosition"));
  const status = document.createElement("span");
  status.className = "sample-live-status";
  status.setAttribute("role", "status");
  // The status carries the loading message for screen readers; this shows it.
  const loadingIndicator = document.createElement("span");
  loadingIndicator.className = "sample-live-loading";
  loadingIndicator.setAttribute("aria-hidden", "true");
  const time = document.createElement("span");
  time.className = "sample-live-time";
  controls.append(playButton, time, fullscreenButton);
  overlay.append(controls, position);
  viewport.append(canvasContainer, loadingIndicator, status, overlay);
  element.append(viewport);
  let canvas: SamplePreviewCanvas | undefined;
  let state: SamplePreviewState = "stopped";
  let disposed = false;
  let pointerInside = false;
  let touchControlsVisible = false;
  let keyboardFocus = false;
  let suppressTouchPlayback = false;
  let pointerFocusPending = false;

  function updateVisibility(): void {
    const playbackStarted = state === "playing" || state === "paused";
    overlay.hidden = !playbackStarted;
    viewport.dataset.controlsVisible = String(playbackStarted && (pointerInside || touchControlsVisible || keyboardFocus));
  }

  function updateFullscreen(): void {
    const fullscreen = document.fullscreenElement === viewport;
    fullscreenButton.replaceChildren(fullscreen ? createExitFullscreenIcon() : createFullscreenIcon());
    fullscreenButton.title = t(fullscreen ? "samples.exitFullscreen" : "samples.fullscreen");
    fullscreenButton.setAttribute("aria-label", fullscreenButton.title);
  }

  function exitFullscreen(): void {
    if (document.fullscreenElement === viewport) {
      void document.exitFullscreen().catch(() => {});
    }
  }


  function placeholder(): void {
    canvasContainer.replaceChildren();
    if (sample.thumbnailUrl !== undefined) {
      const thumbnail = document.createElement("img");
      thumbnail.alt = "";
      thumbnail.loading = "lazy";
      thumbnail.dataset.thumbnailUrl = sample.thumbnailUrl;
      canvasContainer.appendChild(thumbnail);
      observer.observe(thumbnail);
    } else {
      const prompt = document.createElement("span");
      prompt.className = "sample-live-start";
      prompt.appendChild(createPlayIcon());
      canvasContainer.appendChild(prompt);
    }
  }

  function releaseCanvas(): void {
    canvas?.dispose();
    canvas = undefined;
  }

  function updateState(nextState: SamplePreviewState, error?: string): void {
    state = nextState;
    playButton.replaceChildren(state === "playing" ? createPauseIcon() : createPlayIcon());
    playButton.title = state === "playing" ? t("samples.pausePreview") : t("samples.play");
    playButton.setAttribute("aria-label", playButton.title);
    playButton.disabled = state === "loading";
    canvasContainer.disabled = state === "loading";
    canvasContainer.setAttribute("aria-label", playButton.title);
    position.disabled = state !== "playing" && state !== "paused";
    element.dataset.previewState = state;
    status.textContent = state === "loading" ? t("samples.previewLoading")
      : state === "error" ? `${t("samples.previewFailed")} ${error ?? ""}` : "";
    status.setAttribute("role", state === "error" ? "alert" : "status");
    if (state === "stopped" || state === "error") {
      releaseCanvas();
      placeholder();
      position.value = "0";
      time.textContent = "0:00";
      position.style.setProperty("--sample-preview-progress", "0%");
      exitFullscreen();
    }
    updateVisibility();
  }

  function togglePlayback(): void {
    if (state === "playing") {
      player.pause();
    } else if (state === "paused") {
      beforePlay();
      player.resume();
    } else {
      beforePlay();
      void player.start(sample, {
        cycleCompleted: () => {
          if (!disposed) element.dispatchEvent(new CustomEvent("mt-sample-preview-cycle", { bubbles: true, detail: sample.id }));
        },
        stateChanged: (nextState, error) => { if (!disposed) updateState(nextState, error); },
        render: (frame, frameNumber, durationFrames, fps) => {
          if (!disposed) {
            if (canvas === undefined) {
              canvasContainer.replaceChildren();
              canvas = createCanvas(canvasContainer);
            }
            canvas.render(frame);
            position.max = String(durationFrames - 1);
            position.value = String(frameNumber);
            time.textContent = `${formatPreviewTime(frameNumber / fps)} / ${formatPreviewTime(durationFrames / fps)}`;
            const progress = durationFrames > 1 ? frameNumber / (durationFrames - 1) : 0;
            position.style.setProperty("--sample-preview-progress", `${progress * 100}%`);
            position.setAttribute("aria-valuetext", time.textContent);
          }
        },
      });
    }
  }
  playButton.addEventListener("click", togglePlayback);
  canvasContainer.addEventListener("click", () => {
    if (suppressTouchPlayback) suppressTouchPlayback = false;
    else togglePlayback();
  });
  viewport.addEventListener("pointerenter", (event) => {
    if (event.pointerType !== "touch") {
      pointerInside = true;
      updateVisibility();
    }
  });
  viewport.addEventListener("pointerleave", (event) => {
    if (event.pointerType !== "touch") {
      pointerInside = false;
      updateVisibility();
    }
  });
  viewport.addEventListener("pointerdown", (event) => {
    keyboardFocus = false;
    pointerFocusPending = true;
    if (event.pointerType === "touch") {
      pointerInside = false;
      if (canvasContainer.contains(event.target as Node)) {
        touchControlsVisible = !touchControlsVisible;
        suppressTouchPlayback = state === "playing" || state === "paused";
      } else {
        touchControlsVisible = true;
      }
    } else {
      suppressTouchPlayback = false;
      touchControlsVisible = false;
    }
    updateVisibility();
  });
  viewport.addEventListener("pointerup", () => { pointerFocusPending = false; });
  viewport.addEventListener("pointercancel", () => { pointerFocusPending = false; suppressTouchPlayback = false; });
  viewport.addEventListener("keydown", () => {
    pointerFocusPending = false;
    keyboardFocus = true;
    updateVisibility();
  });
  viewport.addEventListener("focusin", (event) => {
    if (!pointerFocusPending && (event.target as Element).matches(":focus-visible")) keyboardFocus = true;
    pointerFocusPending = false;
    updateVisibility();
  });
  viewport.addEventListener("focusout", (event) => {
    if (!viewport.contains(event.relatedTarget as Node | null)) {
      keyboardFocus = false;
      updateVisibility();
    }
  });
  fullscreenButton.addEventListener("click", () => {
    const request = document.fullscreenElement === viewport ? document.exitFullscreen() : viewport.requestFullscreen();
    void request.then(() => { if (disposed) exitFullscreen(); }).catch(() => {
      if (!disposed) {
        status.textContent = t("samples.fullscreenFailed");
        status.setAttribute("role", "alert");
      }
    });
  });
  viewport.addEventListener("fullscreenchange", updateFullscreen);
  updateFullscreen();
  updateVisibility();
  position.addEventListener("input", () => player.seek(Number(position.value)));
  updateState("stopped");
  return {
    element,
    play: () => {
      if (!disposed && state !== "loading" && state !== "playing") togglePlayback();
    },
    dispose: () => {
      disposed = true;
      exitFullscreen();
      releaseCanvas();
    },
  };
}

function formatPreviewTime(seconds: number): string {
  const totalSeconds = Math.max(Math.floor(seconds), 0);
  const minutes = Math.floor(totalSeconds / 60);
  const remainder = String(totalSeconds % 60).padStart(2, "0");
  return `${minutes}:${remainder}`;
}
