import type { CtxCameraData, CtxCharacterData, CtxGlobalData, CtxPartData } from "./ctxBindings";
import { flattenPathCached } from "./flattenCache";
import type { Jacobian2D } from "./renderUnits";
import type { LocalRect, NaturalCharacter, PartGeometry } from "./sceneGeometry";

export interface Point3D {
  x: number;
  y: number;
  z: number;
}

export interface ProjectedPartGeometry {
  pathData?: string;
  clipPathData?: string;
  boxPathData: string;
  depth: number;
}

const kDegreesToRadians = Math.PI / 180;
const kNearEpsilonRatio = 0.001;
const kProjectionCurveSegments = 8;
const kJacobianStep = 0.5;

export class Projection3DProjector {
  private readonly camera: OrbitCamera;

  constructor(
    private readonly canvasWidth: number,
    private readonly canvasHeight: number,
    private readonly global: CtxGlobalData,
    camera: CtxCameraData,
  ) {
    this.camera = new OrbitCamera(canvasWidth, canvasHeight, camera);
  }

  projectPart(
    natural: NaturalCharacter,
    geometry: PartGeometry,
    character: CtxCharacterData,
    part: CtxPartData,
  ): ProjectedPartGeometry {
    // A pose or a camera that cannot be carried out in numbers (a depth of 1e308, a camera at infinity) leaves the part nothing
    // to draw, and no depth that is not a number to sort on.
    let finite = true;
    const projectLocalPoint = (x: number, y: number): ProjectedPoint => {
      const projected = this.projectPoint(
        { x: x + natural.centerX, y: y + natural.centerY, z: part.z * this.canvasHeight },
        natural,
        geometry,
        character,
        part,
      );
      finite = finite && isFiniteProjected(projected);
      return projected;
    };
    const projectedPath = geometry.pathData === undefined
      ? undefined
      : flattenPathCached(geometry.pathData, kProjectionCurveSegments)
        .map((subpath) => pathFromPoints(subpath.points.map((point) => projectLocalPoint(point.x, point.y)), subpath.closed))
        .join("");
    const clipPathData = geometry.clipRect === undefined
      ? undefined
      : this.projectRectangle(geometry.clipRect, projectLocalPoint);
    const boxPathData = this.projectRectangle({
      x: geometry.centerX - natural.centerX - geometry.width / 2,
      y: geometry.centerY - natural.centerY - geometry.height / 2,
      width: geometry.width,
      height: geometry.height,
    }, projectLocalPoint);
    const center = this.projectPoint(
      { x: geometry.centerX, y: geometry.centerY, z: part.z * this.canvasHeight },
      natural,
      geometry,
      character,
      part,
    );
    finite = finite && isFiniteProjected(center);
    if (!finite) {
      return { pathData: projectedPath === undefined ? undefined : "", clipPathData: clipPathData === undefined ? undefined : "", boxPathData: "", depth: 0 };
    }
    return { pathData: projectedPath, clipPathData, boxPathData, depth: center.depth };
  }

  // Central differences of the projection at the part's center, in canvas pixels per local pixel.
  projectPartJacobian(
    natural: NaturalCharacter,
    geometry: PartGeometry,
    character: CtxCharacterData,
    part: CtxPartData,
  ): Jacobian2D {
    const localCenterX = geometry.centerX - natural.centerX;
    const localCenterY = geometry.centerY - natural.centerY;
    const projectLocalPoint = (x: number, y: number): ProjectedPoint =>
      this.projectPoint(
        { x: x + natural.centerX, y: y + natural.centerY, z: part.z * this.canvasHeight },
        natural,
        geometry,
        character,
        part,
      );
    const right = projectLocalPoint(localCenterX + kJacobianStep, localCenterY);
    const left = projectLocalPoint(localCenterX - kJacobianStep, localCenterY);
    const down = projectLocalPoint(localCenterX, localCenterY + kJacobianStep);
    const up = projectLocalPoint(localCenterX, localCenterY - kJacobianStep);
    const span = 2 * kJacobianStep;
    const jacobian = {
      dxdx: (right.x - left.x) / span,
      dxdy: (down.x - up.x) / span,
      dydx: (right.y - left.y) / span,
      dydy: (down.y - up.y) / span,
    };
    return Object.values(jacobian).every(Number.isFinite) ? jacobian : { dxdx: 1, dxdy: 0, dydx: 0, dydy: 1 };
  }

  projectCharacterCenter(
    natural: NaturalCharacter,
    character: CtxCharacterData,
  ): { x: number; y: number; depth: number } {
    const pointAfterCharacter = applyCharacterTransform(
      { x: natural.boundingCenterX, y: natural.boundingCenterY, z: 0 },
      natural,
      character,
      this.canvasWidth,
      this.canvasHeight,
    );
    const projected = this.camera.project(applyGlobalTransform(
      pointAfterCharacter,
      this.global,
      this.canvasWidth,
      this.canvasHeight,
    ));
    return isFiniteProjected(projected) ? projected : { x: 0, y: 0, depth: 0 };
  }

  private projectRectangle(
    rectangle: LocalRect,
    projectPoint: (x: number, y: number) => ProjectedPoint,
  ): string {
    return pathFromPoints([
      projectPoint(rectangle.x, rectangle.y),
      projectPoint(rectangle.x + rectangle.width, rectangle.y),
      projectPoint(rectangle.x + rectangle.width, rectangle.y + rectangle.height),
      projectPoint(rectangle.x, rectangle.y + rectangle.height),
    ], true);
  }

  private projectPoint(
    point: Point3D,
    natural: NaturalCharacter,
    geometry: PartGeometry,
    character: CtxCharacterData,
    part: CtxPartData,
  ): ProjectedPoint {
    const pointAfterPart = applyPartTransform(
      point,
      geometry,
      part,
      this.canvasWidth,
      this.canvasHeight,
    );
    const pointAfterCharacter = applyCharacterTransform(
      pointAfterPart,
      natural,
      character,
      this.canvasWidth,
      this.canvasHeight,
    );
    return this.camera.project(applyGlobalTransform(
      pointAfterCharacter,
      this.global,
      this.canvasWidth,
      this.canvasHeight,
    ));
  }
}

interface ProjectedPoint {
  x: number;
  y: number;
  depth: number;
}

function isFiniteProjected(point: ProjectedPoint): boolean {
  return Number.isFinite(point.x) && Number.isFinite(point.y) && Number.isFinite(point.depth);
}

// Where a point of a shape's own space (its origin at the shape's position) lands on the plane the shape cameras look
// at: the shape's pose, then its parent's, and so on up to the plane. A pose is affine, so the whole chain is one
// matrix, made per shape from its parent's and applied to each vertex without walking the ancestors again.
// Row-major 3x4: x' = m[0]x + m[1]y + m[2]z + m[3], and likewise for y' with m[4..7] and z' with m[8..11].
export interface ShapePlace {
  readonly m: readonly number[];
}

export function mapThroughPlace(place: ShapePlace, point: Point3D): Point3D {
  const m = place.m;
  return {
    x: m[0] * point.x + m[1] * point.y + m[2] * point.z + m[3],
    y: m[4] * point.x + m[5] * point.y + m[6] * point.z + m[7],
    z: m[8] * point.x + m[9] * point.y + m[10] * point.z + m[11],
  };
}

// The pose of a shape alone: it turns about its own position, not the middle of its outline, so the pose is about the
// origin.
export function applyShapePose(
  point: Point3D,
  shape: CtxCharacterData,
  canvasWidth: number,
  canvasHeight: number,
): Point3D {
  return applyPoseAbout(point, 0, 0, shape, canvasWidth, canvasHeight);
}

// The pose of a shape as a matrix, in the form of ShapePlace. Its turn and scale are built from the pose directly, apart
// from every move, so a large move cannot cost them their digits; the move is worked out last from the pivot and the
// offsets: the pivot stays where it is, and the shape is then placed by the offsets.
function shapePoseMatrix(shape: CtxCharacterData, canvasWidth: number, canvasHeight: number): number[] {
  const scaleX = shape.scale * shape.stretch_x;
  const scaleY = shape.scale * shape.stretch_y;
  const yaw = shape.yaw * kDegreesToRadians;
  const pitch = shape.pitch * kDegreesToRadians;
  const rotation = shape.rotation * kDegreesToRadians;
  // Each column is where the scaled axis goes: scale, then pitch and yaw, then the turn in the plane.
  const column = (axis: Point3D): Point3D =>
    rotateZ(rotateObjectYawPitch({ x: axis.x * scaleX, y: axis.y * scaleY, z: axis.z }, yaw, pitch), rotation);
  const axisX = column({ x: 1, y: 0, z: 0 });
  const axisY = column({ x: 0, y: 1, z: 0 });
  const axisZ = column({ x: 0, y: 0, z: 1 });
  const anchorX = (shape.pivot_x - 0.5) * canvasWidth;
  const anchorY = -(shape.pivot_y - 0.5) * canvasHeight;
  const moveX = anchorX + (shape.offset_x - 0.5) * canvasWidth;
  const moveY = anchorY - (shape.offset_y - 0.5) * canvasHeight;
  const moveZ = shape.z * canvasHeight;
  return [
    axisX.x, axisY.x, axisZ.x, moveX - (axisX.x * anchorX + axisY.x * anchorY),
    axisX.y, axisY.y, axisZ.y, moveY - (axisX.y * anchorX + axisY.y * anchorY),
    axisX.z, axisY.z, axisZ.z, moveZ - (axisX.z * anchorX + axisY.z * anchorY),
  ];
}

// The place of a shape that lies on the canvas plane with the Global at rest (the canvas center is the origin of
// the shapes), under its parent's place when it has one.
export function shapePlaceOf(
  shape: CtxCharacterData,
  parent: ShapePlace | undefined,
  canvasWidth: number,
  canvasHeight: number,
): ShapePlace {
  const pose = shapePoseMatrix(shape, canvasWidth, canvasHeight);
  const outer = parent?.m ?? [1, 0, 0, canvasWidth / 2, 0, 1, 0, canvasHeight / 2, 0, 0, 1, 0];
  const composed: number[] = [];
  for (let row = 0; row < 3; row += 1) {
    for (let column = 0; column < 3; column += 1) {
      composed.push(
        outer[row * 4] * pose[column] + outer[row * 4 + 1] * pose[4 + column] + outer[row * 4 + 2] * pose[8 + column],
      );
    }
    composed.push(
      outer[row * 4] * pose[3] + outer[row * 4 + 1] * pose[7] + outer[row * 4 + 2] * pose[11] + outer[row * 4 + 3],
    );
  }
  return { m: composed };
}

export interface ProjectedShape {
  pathData: string;
  boxPathData: string;
  depth: number;
  jacobian: Jacobian2D;
}

// The cameras that view shapes, numbered from one, each an orbit camera of its own. A shape that names a camera
// beyond those given is seen by one at the defaults.
export class ShapeCameraProjector {
  private readonly cameras: OrbitCamera[];
  private readonly defaultCamera: OrbitCamera;

  constructor(
    canvasWidth: number,
    canvasHeight: number,
    cameras: readonly CtxCameraData[],
    defaultCamera: CtxCameraData,
  ) {
    this.cameras = cameras.map((camera) => new OrbitCamera(canvasWidth, canvasHeight, camera));
    this.defaultCamera = new OrbitCamera(canvasWidth, canvasHeight, defaultCamera);
  }

  projectShape(
    place: ShapePlace,
    cameraNumber: number,
    pathData: string,
    bounds: { centerX: number; centerY: number; width: number; height: number },
  ): ProjectedShape {
    const camera = this.cameras[cameraNumber - 1] ?? this.defaultCamera;
    // A place or a camera that cannot be carried out in numbers (a depth of 1e308, a perspective that puts the camera at
    // infinity) leaves the shape nothing to draw, and no depth that is not a number to sort on.
    let finite = true;
    const projectLocal = (x: number, y: number): ProjectedPoint => {
      const projected = camera.project(mapThroughPlace(place, { x, y, z: 0 }));
      finite = finite && Number.isFinite(projected.x) && Number.isFinite(projected.y) && Number.isFinite(projected.depth);
      return projected;
    };
    const pathProjected = flattenPathCached(pathData, kProjectionCurveSegments)
      .map((subpath) => pathFromPoints(subpath.points.map((point) => projectLocal(point.x, point.y)), subpath.closed))
      .join("");
    const left = bounds.centerX - bounds.width / 2;
    const top = bounds.centerY - bounds.height / 2;
    const boxPathData = pathFromPoints([
      projectLocal(left, top),
      projectLocal(left + bounds.width, top),
      projectLocal(left + bounds.width, top + bounds.height),
      projectLocal(left, top + bounds.height),
    ], true);
    const right = projectLocal(bounds.centerX + kJacobianStep, bounds.centerY);
    const leftPoint = projectLocal(bounds.centerX - kJacobianStep, bounds.centerY);
    const down = projectLocal(bounds.centerX, bounds.centerY + kJacobianStep);
    const up = projectLocal(bounds.centerX, bounds.centerY - kJacobianStep);
    const span = 2 * kJacobianStep;
    const depth = projectLocal(bounds.centerX, bounds.centerY).depth;
    if (!finite) {
      return { pathData: "", boxPathData: "", depth: 0, jacobian: { dxdx: 1, dxdy: 0, dydx: 0, dydy: 1 } };
    }
    return {
      pathData: pathProjected,
      boxPathData,
      depth,
      jacobian: {
        dxdx: (right.x - leftPoint.x) / span,
        dxdy: (down.x - up.x) / span,
        dydx: (right.y - leftPoint.y) / span,
        dydy: (down.y - up.y) / span,
      },
    };
  }
}

class OrbitCamera {
  private readonly cameraPosition: Point3D;
  private readonly screenCenterX: number;
  private readonly screenCenterY: number;
  private readonly focalLength: number;
  private readonly yaw: number;
  private readonly pitch: number;
  private readonly nearEpsilon: number;

  constructor(canvasWidth: number, canvasHeight: number, camera: CtxCameraData) {
    this.yaw = camera.yaw * kDegreesToRadians;
    this.pitch = camera.pitch * kDegreesToRadians;
    const target = {
      x: canvasWidth * camera.target_x,
      y: canvasHeight * (1 - camera.target_y),
      z: 0,
    };
    const distanceFactor = perspectiveToDistance(camera.perspective);
    const distance = distanceFactor * canvasHeight;
    const direction = rotateYawPitch({ x: 0, y: 0, z: 1 }, this.yaw, this.pitch);
    this.cameraPosition = {
      x: target.x - distance * direction.x,
      y: target.y - distance * direction.y,
      z: target.z - distance * direction.z,
    };
    this.screenCenterX = canvasWidth * (0.5 + camera.lens_shift_x);
    this.screenCenterY = canvasHeight * (0.5 - camera.lens_shift_y);
    this.focalLength = distanceFactor * camera.zoom * canvasHeight;
    this.nearEpsilon = kNearEpsilonRatio * canvasHeight;
  }

  project(worldPoint: Point3D): ProjectedPoint {
    const relative = {
      x: worldPoint.x - this.cameraPosition.x,
      y: worldPoint.y - this.cameraPosition.y,
      z: worldPoint.z - this.cameraPosition.z,
    };
    const view = inverseRotateYawPitch(relative, this.yaw, this.pitch);
    const safeDepth = Math.max(view.z, this.nearEpsilon);
    return {
      x: this.screenCenterX + this.focalLength * view.x / safeDepth,
      y: this.screenCenterY + this.focalLength * view.y / safeDepth,
      depth: view.z,
    };
  }
}

export function perspectiveToDistance(perspective: number): number {
  let inverseDistance = 0.5;
  if (perspective <= 0.5) {
    inverseDistance = 0.1 + 0.4 * (perspective / 0.5);
  } else {
    inverseDistance = 0.5 + 4.5 * ((perspective - 0.5) / 0.5);
  }
  return 1 / inverseDistance;
}

function applyPartTransform(
  point: Point3D,
  geometry: PartGeometry,
  part: CtxPartData,
  canvasWidth: number,
  canvasHeight: number,
): Point3D {
  const anchor = {
    x: geometry.centerX + (part.pivot_x - 0.5) * canvasWidth,
    y: geometry.centerY - (part.pivot_y - 0.5) * canvasHeight,
  };
  let result = {
    x: (point.x - anchor.x) * part.scale * part.stretch_x,
    y: (point.y - anchor.y) * part.scale * part.stretch_y,
    z: point.z,
  };
  result = rotateObjectYawPitch(result, part.yaw * kDegreesToRadians, part.pitch * kDegreesToRadians);
  result = rotateZ(result, part.rotation * kDegreesToRadians);
  return {
    x: result.x + anchor.x + (part.offset_x - 0.5) * canvasWidth,
    y: result.y + anchor.y - (part.offset_y - 0.5) * canvasHeight,
    z: result.z,
  };
}

function applyCharacterTransform(
  point: Point3D,
  natural: NaturalCharacter,
  character: CtxCharacterData,
  canvasWidth: number,
  canvasHeight: number,
): Point3D {
  return applyPoseAbout(point, natural.boundingCenterX, natural.boundingCenterY, character, canvasWidth, canvasHeight);
}

// The pose of a character about the given center: its pivot is measured from there, and it is placed by the offset.
function applyPoseAbout(
  point: Point3D,
  centerX: number,
  centerY: number,
  character: CtxCharacterData,
  canvasWidth: number,
  canvasHeight: number,
): Point3D {
  const anchor = {
    x: centerX + (character.pivot_x - 0.5) * canvasWidth,
    y: centerY - (character.pivot_y - 0.5) * canvasHeight,
  };
  let result = {
    x: (point.x - anchor.x) * character.scale * character.stretch_x,
    y: (point.y - anchor.y) * character.scale * character.stretch_y,
    z: point.z,
  };
  result = rotateObjectYawPitch(result, character.yaw * kDegreesToRadians, character.pitch * kDegreesToRadians);
  result = rotateZ(result, character.rotation * kDegreesToRadians);
  return {
    x: result.x + anchor.x + (character.offset_x - 0.5) * canvasWidth,
    y: result.y + anchor.y - (character.offset_y - 0.5) * canvasHeight,
    z: result.z + character.z * canvasHeight,
  };
}

function applyGlobalTransform(
  point: Point3D,
  global: CtxGlobalData,
  canvasWidth: number,
  canvasHeight: number,
): Point3D {
  const pivot = {
    x: (global.pivot_x - 0.5) * canvasWidth,
    y: -(global.pivot_y - 0.5) * canvasHeight,
  };
  let result = {
    x: (point.x - pivot.x) * global.scale * global.stretch_x,
    y: (point.y - pivot.y) * global.scale * global.stretch_y,
    z: point.z,
  };
  result = rotateObjectYawPitch(result, global.yaw * kDegreesToRadians, global.pitch * kDegreesToRadians);
  result = rotateZ(result, global.rotation * kDegreesToRadians);
  return {
    x: result.x + pivot.x + global.position_x * canvasWidth,
    y: result.y + pivot.y + (1 - global.position_y) * canvasHeight,
    z: result.z,
  };
}

// The camera orbit direction: a positive yaw turns +X toward +Z (away from the viewer) and a positive pitch
// turns -Y toward +Z.
function rotateYawPitch(point: Point3D, yaw: number, pitch: number): Point3D {
  const cosineYaw = Math.cos(yaw);
  const sineYaw = Math.sin(yaw);
  const cosinePitch = Math.cos(pitch);
  const sinePitch = Math.sin(pitch);
  return {
    x: cosineYaw * point.x + sineYaw * sinePitch * point.y - sineYaw * cosinePitch * point.z,
    y: cosinePitch * point.y + sinePitch * point.z,
    z: sineYaw * point.x - cosineYaw * sinePitch * point.y + cosineYaw * cosinePitch * point.z,
  };
}

// The pose of an object (Global, character or part): the host's Ry(yaw) * Rx(pitch), the opposite sense of the
// camera orbit. A positive yaw brings the right end nearer and a positive pitch brings the top end nearer.
function rotateObjectYawPitch(point: Point3D, yaw: number, pitch: number): Point3D {
  const cosineYaw = Math.cos(yaw);
  const sineYaw = Math.sin(yaw);
  const cosinePitch = Math.cos(pitch);
  const sinePitch = Math.sin(pitch);
  return {
    x: cosineYaw * point.x + sineYaw * sinePitch * point.y + sineYaw * cosinePitch * point.z,
    y: cosinePitch * point.y - sinePitch * point.z,
    z: -sineYaw * point.x + cosineYaw * sinePitch * point.y + cosineYaw * cosinePitch * point.z,
  };
}

function inverseRotateYawPitch(point: Point3D, yaw: number, pitch: number): Point3D {
  const cosineYaw = Math.cos(yaw);
  const sineYaw = Math.sin(yaw);
  const cosinePitch = Math.cos(pitch);
  const sinePitch = Math.sin(pitch);
  return {
    x: cosineYaw * point.x + sineYaw * point.z,
    y: sineYaw * sinePitch * point.x + cosinePitch * point.y - cosineYaw * sinePitch * point.z,
    z: -sineYaw * cosinePitch * point.x + sinePitch * point.y + cosineYaw * cosinePitch * point.z,
  };
}

function rotateZ(point: Point3D, angle: number): Point3D {
  const cosine = Math.cos(angle);
  const sine = Math.sin(angle);
  return {
    x: cosine * point.x - sine * point.y,
    y: sine * point.x + cosine * point.y,
    z: point.z,
  };
}

function pathFromPoints(points: readonly ProjectedPoint[], closed: boolean): string {
  let result = "";
  if (points.length > 0) {
    result = `M${points[0].x},${points[0].y}`;
    for (const point of points.slice(1)) {
      result += `L${point.x},${point.y}`;
    }
    if (closed) {
      result += "Z";
    }
  }
  return result;
}
