import type { EvaluatedFrame } from "../../core/frameEvaluator";
import { resizeCanvasBuffer } from "../../core/canvasBuffer";
import { renderFrame } from "../../core/renderer";
import { createBrowserBlurHost } from "../../webview/browserBlurHost";

export interface SamplePreviewCanvas {
  render: (frame: EvaluatedFrame) => void;
  dispose: () => void;
}

export type SamplePreviewCanvasFactory = (container: HTMLElement) => SamplePreviewCanvas;

export function createSamplePreviewCanvas(container: HTMLElement): SamplePreviewCanvas {
  const canvas = document.createElement("canvas");
  canvas.className = "sample-live-render-canvas";
  container.appendChild(canvas);
  const context = canvas.getContext("2d");
  if (context === null) throw new Error("2D canvas context unavailable");
  const blur = createBrowserBlurHost();
  let lastFrame: EvaluatedFrame | undefined;

  function draw(): void {
    if (lastFrame !== undefined && context !== null) {
      const fitScale = Math.min(Math.max(container.clientWidth, 1) / lastFrame.canvasWidth,
        Math.max(container.clientHeight, 1) / lastFrame.canvasHeight);
      const ratio = window.devicePixelRatio || 1;
      canvas.style.width = `${lastFrame.canvasWidth * fitScale}px`;
      canvas.style.height = `${lastFrame.canvasHeight * fitScale}px`;
      resizeCanvasBuffer(canvas, lastFrame.canvasWidth * fitScale * ratio, lastFrame.canvasHeight * fitScale * ratio);
      renderFrame(context, lastFrame, fitScale * ratio, { displayMode: "glyph", showIndexLabels: false, blur });
    }
  }

  const observer = new ResizeObserver(draw);
  observer.observe(container);
  return {
    render: (frame) => { lastFrame = frame; draw(); },
    dispose: () => { observer.disconnect(); lastFrame = undefined; },
  };
}
