export function sampleGenrePath(sampleId: string): readonly SampleGenre[] {
  function find(genres: readonly SampleGenre[]): SampleGenre[] {
    let result: SampleGenre[] = [];
    for (const genre of genres) {
      if (genre.sampleIds?.includes(sampleId)) {
        result = [genre];
      } else if (genre.children !== undefined) {
        const descendants = find(genre.children);
        if (descendants.length > 0) result = [genre, ...descendants];
      }
      if (result.length > 0) break;
    }
    return result;
  }
  return find(kSampleGenres);
}
