// Kept equal to the plugin's, so a setting means the same in the preview. The plugin's shader takes the
// gain as a half float, so a gain is held at its largest finite value.
const kGlowGainScale = 10;
const kMaximumGlowGain = 65504;

// The gain a glow strength puts on a blurred shape. No glow, and a strength that is negative or not
// finite, give one: the shape stays as it is.
export function resolveGlowGain(glow: number): number {
  return Number.isFinite(glow) && glow > 0 ? Math.min(1 + glow * kGlowGainScale, kMaximumGlowGain) : 1;
}
