export function parseSampleDescriptions(source) {
  let description = "";
  const descriptions = {};
  const blocks = /--\[\[\s*@description(?:\.([A-Za-z]{2,8}(?:-[A-Za-z0-9]{1,8})*))?(?=\s|\]\])\s*([\s\S]*?)\]\]/g;
  for (const match of source.matchAll(blocks)) {
    const body = match[2].trim();
    if (match[1] === undefined) {
      if (description === "") description = body;
    } else {
      const locale = match[1].toLowerCase();
      if (descriptions[locale] === undefined) descriptions[locale] = body;
    }
  }
  return { description, descriptions };
}

export function localizedSampleDescription(sample, locale) {
  const normalized = locale.toLowerCase();
  return sample.descriptions?.[normalized]?.trim() ||
    sample.descriptions?.[normalized.split("-")[0]]?.trim() || sample.description;
}

export function parseSampleAnimationId(source) {
  return /^--[^\S\r\n]*@animation_id[^\S\r\n]+([A-Z]{3}\d{3})[^\S\r\n]*\r?$/m.exec(source)?.[1];
}
