// Counts the menu offers; each lays out as a near-square grid.
export const kPreviewFrameCountChoices = [4, 6, 9, 12] as const;

// Reads a count from the menu or from storage, falling back to the largest for anything it does not offer.
export function normalizePreviewFrameCount(value: unknown): number {
  let count = Number.NaN;
  if (typeof value === "number") count = value;
  else if (typeof value === "string" && /^[0-9]+$/.test(value)) count = Number(value);
  const offered = kPreviewFrameCountChoices.find((choice) => choice === count);
  return offered ?? Math.max(...kPreviewFrameCountChoices);
}

// Longest edge the AI services take without shrinking the image first.
const kDefaultMaxWidth = 1568;

// Columns by frame count: a near-square grid, wider for a 16:9 canvas.
function defaultColumns(frameCount: number): number {
  let columns = 4;
  if (frameCount <= 2) columns = frameCount;
  else if (frameCount <= 4) columns = 2;
  else if (frameCount <= 9) columns = 3;
  return Math.max(1, columns);
}
const kDefaultGap = 12;
const kDefaultLabelHeight = 28;

export interface PreviewFrameRange {
  startFrame: number;
  // Exclusive, like the timeline's marked range.
  endFrame: number;
}

// Without a marked range, one frame from the middle of each equal share of the clip, so the intro, the
// settled middle and the outro are all represented without taking the first or last frame, which scripts
// often leave blank. A range the user marked is spread evenly with both of its ends included, since the
// user chose those ends to look at. A range covering the whole clip counts as no range.
function resolveRange(durationFrames: number, range?: PreviewFrameRange): { start: number; end: number; marked: boolean } {
  const duration = Math.floor(durationFrames);
  const start = Math.max(0, Math.floor(range?.startFrame ?? 0));
  const end = Math.min(duration, Math.floor(range?.endFrame ?? duration));
  return { start, end, marked: start > 0 || end < duration };
}

export function pickPreviewFrames(durationFrames: number, count: number, range?: PreviewFrameRange): number[] {
  const { start, end, marked } = resolveRange(durationFrames, range);
  const span = end - start;
  const requested = Math.min(Math.floor(count), span);
  const frames: number[] = [];
  for (let index = 0; index < requested; index += 1) {
    if (!marked) {
      frames.push(Math.floor(((index + 0.5) * span) / requested));
    } else if (requested === 1) {
      frames.push(start + Math.floor((span - 1) / 2));
    } else {
      frames.push(start + Math.round((index * (span - 1)) / (requested - 1)));
    }
  }
  return frames;
}

export interface PreviewRangeDescription {
  marked: boolean;
  startFrame: number;
  lastFrame: number;
  startSeconds: number;
  endSeconds: number;
  frameCount: number;
}

// What the sheet will cover, for telling the user before they copy it.
export function describePreviewRange(
  durationFrames: number,
  fps: number,
  range?: PreviewFrameRange,
): PreviewRangeDescription {
  const { start, end, marked } = resolveRange(durationFrames, range);
  const frameCount = Math.max(0, end - start);
  return {
    marked,
    startFrame: start,
    lastFrame: end - 1,
    startSeconds: fps > 0 ? start / fps : 0,
    endSeconds: fps > 0 ? end / fps : 0,
    frameCount,
  };
}

export function previewFrameLabel(frame: number, fps: number): string {
  return fps > 0 ? `Frame ${frame} (${(frame / fps).toFixed(2)} s)` : `Frame ${frame}`;
}

export interface PreviewSheetOptions {
  maxWidth?: number;
  columns?: number;
  gap?: number;
  labelHeight?: number;
}

export interface PreviewSheetCell {
  frame: number;
  x: number;
  y: number;
  width: number;
  height: number;
  labelY: number;
}

export interface PreviewSheetLayout {
  width: number;
  height: number;
  scale: number;
  labelHeight: number;
  cells: PreviewSheetCell[];
}

// Rows of labelled frames on one sheet. A frame is never drawn larger than its canvas.
export function layoutPreviewSheet(
  frames: readonly number[],
  canvasWidth: number,
  canvasHeight: number,
  options: PreviewSheetOptions = {},
): PreviewSheetLayout {
  if (frames.length === 0) {
    throw new RangeError("a preview sheet needs at least one frame");
  }
  if (!(canvasWidth > 0) || !(canvasHeight > 0) || !Number.isFinite(canvasWidth) || !Number.isFinite(canvasHeight)) {
    throw new RangeError("the canvas must have a positive size");
  }
  const maxWidth = options.maxWidth ?? kDefaultMaxWidth;
  const gap = options.gap ?? kDefaultGap;
  const labelHeight = options.labelHeight ?? kDefaultLabelHeight;
  const columns = Math.min(frames.length, Math.max(1, Math.floor(options.columns ?? defaultColumns(frames.length))));
  const rows = Math.ceil(frames.length / columns);
  const availableWidth = Math.floor((maxWidth - gap * (columns + 1)) / columns);
  const scale = Math.min(1, availableWidth / canvasWidth);
  const cellWidth = Math.max(1, Math.round(canvasWidth * scale));
  const cellHeight = Math.max(1, Math.round(canvasHeight * scale));
  const cells = frames.map((frame, index): PreviewSheetCell => {
    const row = Math.floor(index / columns);
    const labelY = gap + row * (labelHeight + cellHeight + gap);
    return {
      frame,
      x: gap + (index % columns) * (cellWidth + gap),
      y: labelY + labelHeight,
      width: cellWidth,
      height: cellHeight,
      labelY,
    };
  });
  return {
    width: gap * (columns + 1) + columns * cellWidth,
    height: gap + rows * (labelHeight + cellHeight + gap),
    scale,
    labelHeight,
    cells,
  };
}

const kSheetBackground = "#1b1b1b";
const kSheetLabelColor = "#e6e6e6";
const kLabelFontRatio = 0.6;

// The parts of a 2D context the sheet needs, so the drawing can be exercised without a browser.
export interface PreviewSheetContext<TImage> {
  fillStyle: unknown;
  font: string;
  textBaseline: string;
  fillRect(x: number, y: number, width: number, height: number): void;
  fillText(text: string, x: number, y: number): void;
  drawImage(image: TImage, x: number, y: number): void;
}

// Paints the background, then each cell's image under its label. A cell whose image cannot be produced
// keeps an empty slot and no label, so the labels always describe what is drawn beneath them.
export function drawPreviewSheet<TImage>(
  context: PreviewSheetContext<TImage>,
  layout: PreviewSheetLayout,
  fps: number,
  drawCell: (cell: PreviewSheetCell) => TImage | undefined,
): void {
  context.fillStyle = kSheetBackground;
  context.fillRect(0, 0, layout.width, layout.height);
  context.font = `${Math.round(layout.labelHeight * kLabelFontRatio)}px sans-serif`;
  context.textBaseline = "middle";
  for (const cell of layout.cells) {
    const image = drawCell(cell);
    if (image !== undefined) {
      context.drawImage(image, cell.x, cell.y);
      context.fillStyle = kSheetLabelColor;
      context.fillText(previewFrameLabel(cell.frame, fps), cell.x, cell.labelY + layout.labelHeight / 2);
    }
  }
}
