// What the preview needs to hint at a material: the kind, the controls a hint can vary with, and
// the tint. The simulator never reproduces the real shaders, so this stops at the resolved values.
export interface ResolvedTexture {
  type: CtxTextureData["type"];
  p1: number;
  p2: number;
  p3: number;
  p4: number;
  p5: number;
  color: Rgba;
}

function resolveTexture(
  inherited: ResolvedTexture,
  own: CtxIndividualTextureData,
): ResolvedTexture {
  return own.use
    ? { type: own.type, p1: own.p1, p2: own.p2, p3: own.p3, p4: own.p4, p5: own.p5, color: { ...own.color } }
    : inherited;
}

// A box that paints no material. Also the value fixtures start from, so adding a field to
// ResolvedTexture does not have to be repeated across every renderer test.
export function noTexture(): ResolvedTexture {
  return { type: "none", p1: 0.5, p2: 0.5, p3: 0.5, p4: 0, p5: 0, color: { r: 1, g: 1, b: 1, a: 1 } };
}

function globalTexture(texture: CtxTextureData): ResolvedTexture {
  return {
    type: texture.type,
    p1: texture.p1,
    p2: texture.p2,
    p3: texture.p3,
    p4: texture.p4,
    p5: texture.p5,
    color: { ...texture.color },
  };
}

export interface EvaluatedBox {
  index: number;
  // This part's shadow offset in canvas pixels, measured in the part's own space. Absent on
  // character boxes, which draw no shadow of their own.
  shadowOffsetX?: number;
  shadowOffsetY?: number;
  // The part's blur and its shadow's blur as Gaussian sigmas in canvas pixels, already snapped to the
  // grid the host uses. Absent on character boxes.
  blurX?: number;
  blurY?: number;
  shadowBlurX?: number;
  shadowBlurY?: number;
  // What the shadow's glow strength resolves to: the gain on the blurred shadow. Absent on character boxes.
  shadowGlowGain?: number;
  // What the text blur's glow strength resolves to: the gain on the blurred text. Absent on character boxes.
  blurGlowGain?: number;
  centerX: number;
  centerY: number;
  width: number;
  height: number;
  matrix: Mat2D;
  fillColor: Rgba;
  // Resolved global*character*part opacity multiplier applied on top of fillColor/strokeColor/
  // shadowColor's own alpha at draw time.
  opacity: number;
  useGradientFill: boolean;
  // Whether the fill is drawn and shadowed: the scene's Transparent fill hides it unless the character or the
  // part has its own colour, as on the host. Absent means visible.
  fillVisible?: boolean;
  strokeWidth: number;
  strokeGap: number;
  strokeColor: Rgba;
  outerStrokeWidth?: number;
  outerStrokeColor?: Rgba;
  shadowColor: Rgba;
  // Mirrors Native's resolved useIndividualShadowColor_: true when this box (or, for a part, its
  // owning character) opted into an individual shadow color. The shadow pass draws a box when this
  // is true even while the global shadow is off (frame.shadowEnabled false), matching how Native's
  // shadow pass is gated per box instead of by the global toggle alone.
  hasIndividualShadow: boolean;
  // Resolved through the same global -> character -> part cascade Native runs, so the preview can
  // show which material a box ended up with. The simulator only hints at the material rather than
  // reproducing it, so nothing here carries the shader's own parameters beyond p1 to p4. Optional
  // because the renderer must also draw boxes assembled without it, which is how several of its
  // tests build their frames.
  texture?: ResolvedTexture;
  characterIndex: number;
  // Set on the boxes of a shape, which is fixed to the canvas and sits outside the text: the layer
  // it paints in.
  shapeLayer?: "back" | "front";
  // Set with shapeLayer: the key that orders the shapes of one layer from the lowest.
  shapeZIndex?: number;
  // Set with shapeLayer: the number of the camera for shapes that projects this shape, 0 for none. The shape is then
  // drawn from its projected paths, and projectionDepth orders it among the shapes of the same camera.
  shapeCamera?: number;
  text?: string;
  // True when the source character is whitespace without a glyph outline;
  // such parts follow the show-spaces display setting.
  isSpace?: boolean;
  // Character-center-relative outline (present when a font is loaded). The
  // renderer translates by (originX, originY) before filling.
  pathData?: string;
  originX?: number;
  originY?: number;
  // A single-part glyph's outline groups, stroked one at a time outside the others (see PartGeometry).
  strokeOutlines?: string[];
  // Present in fixed part mode: the slice of the outline this part draws.
  clipRect?: LocalRect;
  // Drawn with the browser's emoji font instead of pathData, which then only marks its square.
  emoji?: EmojiCell;
  // Canvas-space paths produced by the lightweight perspective projector.
  projectedPathData?: string;
  projectedClipPathData?: string;
  projectedBoxPathData?: string;
  projectedStrokeOutlines?: string[];
  projectionDepth?: number;
  projectedCenterX?: number;
  projectedCenterY?: number;
}

export interface EvaluatedGradient {
  enabled: boolean;
  startColor: Rgba;
  endColor: Rgba;
  midpoint: number;
  angle: number;
  start: number;
  end: number;
}

export interface EvaluatedFrame {
  frame: number;
  time: number;
  canvasWidth: number;
  canvasHeight: number;
  backgroundColor: Rgba;
  checkerboardBackground: boolean;
  showSpaces: boolean;
  spaceColor: Rgba;
  shadowEnabled: boolean;
  shadowOffsetX: number;
  shadowOffsetY: number;
  gradient: EvaluatedGradient;
  projection3D: boolean;
  characters: EvaluatedBox[];
  parts: EvaluatedBox[];
  // One box per shape, in declaration order. Kept apart from the text's boxes so Write On, the
  // bounding box and the gradient, which all measure the text, never see them. Optional because the
  // renderer must also draw frames assembled without any, which is how its tests build theirs.
  shapes?: EvaluatedBox[];
  scriptInputValues: EvaluatedParameterValues;
  scriptOutputValues: EvaluatedParameterValues;
  requestedFontName?: string;
  errors: string[];
  warnings: string[];
}

export interface EvaluatedParameterValues {
  global: CtxGlobalData;
  camera: CtxCameraData;
  characters: CtxCharacterData[];
  parts: CtxPartData[];
  boundingBox: CtxBoundingBoxData;
  output: CtxOutputData;
}

export interface EvaluationLimits {
  maxCharacters: number;
  maxParts: number;
  // Shapes use no character or part slot; the limit is the same for every preset.
  maxShapes?: number;
}

export interface SceneTopology {
  characterCount: number;
  partCount: number;
}

const kFrameSeedMultiplier = 2654435761;
// The Scripting preset's limits, the largest any preset has. A host that simulates another preset
// passes that preset's limits to setLimits.
const kDefaultLimits: EvaluationLimits = { maxCharacters: 512, maxParts: 1024 };
const kDefaultMaxShapes = 1024;
const kNormalizedUnitsPerEm = 1000;
// The simulator previews a single instance, so ctx.meta.instance_seed is a fixed value rather than
// one derived from a host instance ID (see ScriptStage::mixInstanceSeed on the plugin side).
const kSimulatorInstanceSeed = 0x1a2b3c4d;

// The host hands a script one margin per character slot even where the preset has no per-character
// parameters, so the script sees the same shape whichever preset is simulated.
function withMarginSlots(global: CtxGlobalData, slotCount: number): CtxGlobalData {
  const margins = [...global.margins];
  while (margins.length < slotCount) {
    margins.push(0);
  }
  return { ...global, margins };
}

// Drops the zero padding the script was given, so only what the script changed differs from the
// Inspector's margins: entries up to the input length or the last non-zero one are kept.
function withoutMarginPadding(global: CtxGlobalData, inputLength: number): CtxGlobalData {
  // A table returned from Lua arrives keyed by index rather than as an array.
  const margins = Object.values(global.margins ?? []);
  let length = margins.length;
  while (length > inputLength && margins[length - 1] === 0) {
    length -= 1;
  }
  return { ...global, margins: margins.slice(0, length) };
}

function frameSeed(frame: number, hookIndex: number): number {
  return ((Math.imul(Math.floor(frame), kFrameSeedMultiplier) + hookIndex) >>> 0) % 0x7fffffff;
}

function createCtxMeta(scene: Scene, limits: EvaluationLimits): CtxMetaData {
  return {
    api_level: kScriptApiLevel,
    plugin_version: kPluginVersion,
    capabilities: {
      has_3d: scene.settings.projection3D,
    },
    limits: {
      max_characters: limits.maxCharacters,
      max_parts: limits.maxParts,
      max_shapes: limits.maxShapes ?? kDefaultMaxShapes,
    },
    instance_seed: kSimulatorInstanceSeed,
  };
}

function createScriptInputs(scene: Scene): CtxScriptInputsData {
  return {
    numbers: [...scene.scriptInputs.numbers],
    colors: scene.scriptInputs.colors.map((color) => ({ ...color })),
    texts: [...scene.scriptInputs.texts],
    booleans: [...scene.scriptInputs.booleans],
  };
}

function createCanvas(width: number, height: number) {
  return {
    width,
    height,
    aspect_ratio: height > 0 ? width / height : 0,
    pixel_aspect_ratio: 1,
  };
}

function createTimeline(scene: Scene, frame: number) {
  const durationFrames = scene.settings.durationFrames;
  return {
    available: true,
    start_frame: 0,
    end_frame: durationFrames,
    duration_frames: durationFrames,
    duration_seconds: durationFrames / scene.settings.fps,
    progress: durationFrames > 0 ? Math.min(Math.max(frame / durationFrames, 0), 1) : 0,
  };
}

export class FrameEvaluator {
  private readonly scriptPipeline: ScriptFramePipeline;
  private readonly sceneGeometry = new SceneGeometry();
  private selectedLayoutEngine: TextLayoutEngine | undefined;
  private readonly layoutEnginesByFamily = new Map<string, TextLayoutEngine>();
  private fontNames: string[] = [];
  private limits: EvaluationLimits = kDefaultLimits;

  constructor(engine: ScriptEngine) {
    this.scriptPipeline = new ScriptFramePipeline(engine);
  }

  setLayoutEngine(layoutEngine: TextLayoutEngine | undefined): void {
    this.selectedLayoutEngine = layoutEngine;
    if (layoutEngine !== undefined) {
      this.layoutEnginesByFamily.set(layoutEngine.familyName(), layoutEngine);
    }
    this.sceneGeometry.setLayoutEngine(layoutEngine);
  }

  registerLayoutEngine(layoutEngine: TextLayoutEngine, requestedFamily?: string): void {
    this.layoutEnginesByFamily.set(layoutEngine.familyName(), layoutEngine);
    if (requestedFamily !== undefined) {
      this.layoutEnginesByFamily.set(requestedFamily, layoutEngine);
    }
  }

  setLimits(limits: EvaluationLimits): void {
    this.limits = { ...limits };
  }

  setFontNames(fontNames: readonly string[]): void {
    this.fontNames = [...fontNames];
  }

  private buildLimitedTopology(
    global: GlobalScene,
    scene: Scene,
    glyphDeclarations: readonly GlyphDeclarationData[] = [],
  ): {
    naturalCharacters: NaturalCharacter[];
    partGeometry: PartGeometry[][];
  } {
    const naturalCharacters = this.sceneGeometry.layoutCharacters(global, scene);
    applyGlyphDeclarations(
      naturalCharacters,
      glyphDeclarations,
      global,
      fontSizePixels(scene.settings.canvasHeight),
    );
    alignNaturalCharacters(naturalCharacters, global);
    naturalCharacters.length = Math.min(naturalCharacters.length, this.limits.maxCharacters);
    const partGeometry = this.sceneGeometry.buildPartGeometry(naturalCharacters, scene, global.singlePartGlyph);

    let retainedCharacterCount = 0;
    let allocatedPartCount = 0;
    while (retainedCharacterCount < naturalCharacters.length && allocatedPartCount < this.limits.maxParts) {
      allocatedPartCount += partGeometry[retainedCharacterCount]?.length ?? 0;
      retainedCharacterCount += 1;
    }
    naturalCharacters.length = retainedCharacterCount;
    partGeometry.length = retainedCharacterCount;
    return { naturalCharacters, partGeometry };
  }

  synchronizeSceneTopology(scene: Scene): SceneTopology {
    this.sceneGeometry.setLayoutEngine(this.selectedLayoutEngine);
    const { naturalCharacters, partGeometry } = this.buildLimitedTopology(scene.global, scene);
    const partCount = partGeometry.reduce((sum, parts) => sum + parts.length, 0);
    while (scene.characters.length < naturalCharacters.length) {
      scene.characters.push(createDefaultCharacterScene());
    }
    while (scene.global.margins.length < naturalCharacters.length) {
      scene.global.margins.push(0);
    }
    while (scene.parts.length < partCount) {
      scene.parts.push(createDefaultPartScene());
    }
    return { characterCount: naturalCharacters.length, partCount };
  }

  // Runs OnInitialize against the current scene snapshot. Must be called
  // after every script (re)load and whenever init-relevant scene inputs
  // change; time changes must NOT trigger it.
  initialize(scene: Scene): { errors: string[]; storage?: unknown } {
    this.sceneGeometry.setLayoutEngine(this.selectedLayoutEngine);
    const initData: InitializeHookData = {
      canvas: createCanvas(scene.settings.canvasWidth, scene.settings.canvasHeight),
      fonts: this.fontNames,
      meta: createCtxMeta(scene, this.limits),
      inputs: createScriptInputs(scene),
    };
    return this.scriptPipeline.initialize(initData);
  }

  evaluate(scene: Scene, frame: number): EvaluatedFrame & { shapes: EvaluatedBox[] } {
    this.sceneGeometry.setLayoutEngine(this.selectedLayoutEngine);
    const { canvasWidth, canvasHeight, fps } = scene.settings;
    const time = frame / fps;
    const errors: string[] = [];
    const warnings: string[] = [];

    const selectedFontName = this.selectedLayoutEngine?.familyName() ?? scene.global.fontName;
    const baseGlobal: GlobalScene = { ...scene.global, text: normalizeTextLineBreaks(scene.global.text), fontName: selectedFontName };
    const baseData: BaseHookData = {
      time,
      frame,
      fps,
      text: baseGlobal.text,
      canvas: createCanvas(canvasWidth, canvasHeight),
      fonts: this.fontNames,
      timeline: createTimeline(scene, frame),
      meta: createCtxMeta(scene, this.limits),
      inputs: createScriptInputs(scene),
      global: withMarginSlots(globalToCtx(baseGlobal), this.limits.maxCharacters),
      camera: cameraToCtx(scene.camera),
      glyph_declarations: [],
    };
    const baseEvaluation = this.scriptPipeline.evaluateBase(baseData, frameSeed(frame, 1));
    errors.push(...baseEvaluation.errors);
    warnings.push(...baseEvaluation.warnings);
    const resolvedGlobal = withoutMarginPadding(baseEvaluation.data.global, baseGlobal.margins.length);
    const resolvedGlobalScene = ctxToGlobal(resolvedGlobal);
    const resolvedCamera = baseEvaluation.data.camera;

    let requestedFontName: string | undefined;
    const resolvedLayoutEngine = this.layoutEnginesByFamily.get(resolvedGlobal.font_name);
    if (resolvedLayoutEngine !== undefined) {
      this.sceneGeometry.setLayoutEngine(resolvedLayoutEngine);
    } else {
      this.sceneGeometry.setLayoutEngine(this.selectedLayoutEngine);
      if (resolvedGlobal.font_name.length > 0 && resolvedGlobal.font_name !== selectedFontName) {
        requestedFontName = resolvedGlobal.font_name;
      }
    }

    const glyphDeclarations = baseEvaluation.succeeded
      ? baseEvaluation.data.glyph_declarations ?? []
      : [];
    const { naturalCharacters, partGeometry } = this.buildLimitedTopology(
      resolvedGlobalScene,
      scene,
      glyphDeclarations,
    );
    const shapeFontSize = fontSizePixels(canvasHeight);
    const shapeDeclarations: readonly ShapeDeclarationData[] = baseEvaluation.succeeded
      ? (baseEvaluation.data.shape_declarations ?? []).slice(0, this.limits.maxShapes ?? kDefaultMaxShapes)
      : [];
    const declaredShapePaths = shapeDeclarations.map(
      (declaration) => normalizedDeclaredPath(declaration.path) ?? "",
    );
    const shapeData: CtxCharacterData[] = shapeDeclarations.map((declaration, shapeIndex) => ({
      ...characterSceneToCtx(createDefaultCharacterScene(), resolvedGlobalScene),
      index: shapeIndex + 1,
      parent: declaration.parent ?? 0,
      camera: declaration.camera ?? 0,
    }));
    // The cameras for shapes start at the text camera's defaults and are moved by OnLayout.
    const defaultShapeCamera = cameraToCtx(createDefaultScene().camera);
    const shapeCameraCount = baseEvaluation.succeeded ? baseEvaluation.data.shape_camera_count ?? 0 : 0;
    const shapeCameraData: CtxCameraData[] = Array.from({ length: shapeCameraCount }, () => ({
      ...defaultShapeCamera,
    }));
    let characterPartStart = 1;
    const characterData = naturalCharacters.map((natural, index) => {
      const characterScene = scene.characters[index] ?? createDefaultCharacterScene();
      const partCount = partGeometry[index].length;
      const character = {
        ...characterSceneToCtx(characterScene, resolvedGlobalScene),
        index: index + 1,
        text: natural.text,
        part_start: characterPartStart,
        part_count: partCount,
        line_index: natural.lineIndex + 1,
        geometry: {
          canvas_origin_x: 0.5 + natural.originX / canvasWidth,
          canvas_origin_y: 0.5 - natural.originY / canvasHeight,
          vertical_origin_x: 0.5 + natural.verticalOriginX / canvasWidth,
          vertical_origin_y: 0.5 - natural.verticalOriginY / canvasHeight,
          bounds_center_x: 0.5 + natural.boundingCenterX / canvasWidth,
          bounds_center_y: 0.5 - natural.boundingCenterY / canvasHeight,
          bounds_width: natural.width / canvasWidth,
          bounds_height: natural.height / canvasHeight,
          advance_x: natural.advanceX / canvasWidth,
          advance_y: -natural.advanceY / canvasHeight,
        },
      };
      characterPartStart += partCount;
      return character;
    });
    let sourcePartIndex = 0;
    const partData: CtxPartData[] = partGeometry.flatMap((parts, characterIndex) =>
      parts.map((geometry, indexInCharacter) => {
        const partScene = scene.parts[sourcePartIndex] ?? createDefaultPartScene();
        const natural = naturalCharacters[characterIndex];
        const part = {
          ...partSceneToCtx(partScene, resolvedGlobalScene),
          index: sourcePartIndex + 1,
          character_index: characterIndex + 1,
          index_in_character: indexInCharacter + 1,
          geometry: {
            local_center_x: (geometry.centerX - natural.boundingCenterX) / canvasWidth,
            local_center_y: -(geometry.centerY - natural.boundingCenterY) / canvasHeight,
            canvas_center_x: 0.5 + geometry.originX / canvasWidth,
            canvas_center_y: 0.5 - geometry.originY / canvasHeight,
            bounds_center_x: 0.5 + geometry.centerX / canvasWidth,
            bounds_center_y: 0.5 - geometry.centerY / canvasHeight,
            bounds_width: geometry.width / canvasWidth,
            bounds_height: geometry.height / canvasHeight,
          },
        };
        sourcePartIndex += 1;
        return part;
      }),
    );

    const layoutHookData: LayoutHookData = {
      time,
      frame,
      fps,
      text: resolvedGlobal.text,
      char_count: naturalCharacters.length,
      part_count: partData.length,
      canvas: createCanvas(canvasWidth, canvasHeight),
      fonts: this.fontNames,
      timeline: createTimeline(scene, frame),
      font: (() => {
        const metrics = this.sceneGeometry.fontMetrics(fontSizePixels(canvasHeight));
        return {
          em_size: fontSizePixels(canvasHeight) / canvasHeight,
          ascent: metrics.ascent / canvasHeight,
          descent: metrics.descent / canvasHeight,
          line_height: metrics.lineHeight / canvasHeight,
          units_per_em: metrics.unitsPerEm,
        };
      })(),
      meta: createCtxMeta(scene, this.limits),
      inputs: createScriptInputs(scene),
      global: resolvedGlobal,
      camera: resolvedCamera,
      shape_count: shapeData.length,
      chars: characterData,
      parts: partData,
      shapes: shapeData,
      shape_paths: declaredShapePaths.map((svg) => ({ path: { svg, units_per_em: kNormalizedUnitsPerEm } })),
      shape_cameras: shapeCameraData,
      bounding_box: boundingBoxToCtx(scene.boundingBox),
      output: outputToCtx(scene.output),
    };
    const layoutEvaluation = baseEvaluation.succeeded
      ? this.scriptPipeline.evaluateLayout(layoutHookData, frameSeed(frame, 2))
      : { data: layoutHookData, succeeded: false, errors: [], warnings: [] };
    errors.push(...layoutEvaluation.errors);
    warnings.push(...layoutEvaluation.warnings);
    const resolvedShapes = layoutEvaluation.data.shapes ?? shapeData;
    const resolvedShapeCameras = layoutEvaluation.data.shape_cameras ?? shapeCameraData;
    const layoutShapePaths = declaredShapePaths.map((declaredPath, shapeIndex) => {
      const record = layoutEvaluation.data.shape_paths?.[shapeIndex];
      return record?.edited === true
        ? editedPathToPixels(record.path, shapeFontSize)
        : scaleSvgPathNumbers(declaredPath, shapeFontSize / kNormalizedUnitsPerEm);
    });
    const resolvedCharacters = layoutEvaluation.data.chars;
    const resolvedParts = layoutEvaluation.data.parts;
    const resolvedBoundingBox = layoutEvaluation.data.bounding_box;
    const resolvedOutput = layoutEvaluation.data.output;
    const projection3DEnabled =
      scene.settings.projection3D && !resolvedOutput.force_disable_3d_projection;

    const flatPartGeometry = partGeometry.flat();
    const normalizedUnitsPerEm = kNormalizedUnitsPerEm;
    const pathFontSize = fontSizePixels(canvasHeight);
    const pathHookData: PathHookData = {
      time,
      frame,
      fps,
      char_count: naturalCharacters.length,
      part_count: partData.length,
      canvas: createCanvas(canvasWidth, canvasHeight),
      fonts: this.fontNames,
      timeline: createTimeline(scene, frame),
      font: (() => {
        const metrics = this.sceneGeometry.fontMetrics(pathFontSize);
        return {
          em_size: pathFontSize / canvasHeight,
          ascent: metrics.ascent / canvasHeight,
          descent: metrics.descent / canvasHeight,
          line_height: metrics.lineHeight / canvasHeight,
          units_per_em: metrics.unitsPerEm,
        };
      })(),
      meta: createCtxMeta(scene, this.limits),
      inputs: createScriptInputs(scene),
      global: layoutEvaluation.data.global,
      camera: layoutEvaluation.data.camera,
      shape_count: shapeData.length,
      chars: layoutEvaluation.data.chars,
      parts: layoutEvaluation.data.parts,
      shapes: resolvedShapes,
      shape_parts: layoutShapePaths.map((pathData, shapeIndex) => ({
        index: shapeIndex + 1,
        character_index: shapeIndex + 1,
        index_in_character: 1,
        line_index: 1,
        text: "",
        path: {
          svg: scaleSvgPathNumbers(pathData, kNormalizedUnitsPerEm / pathFontSize),
          units_per_em: kNormalizedUnitsPerEm,
        },
      })),
      bounding_box: layoutEvaluation.data.bounding_box,
      output: layoutEvaluation.data.output,
      path_parts: partData.map((_part, partIndex) => {
        const part = partData[partIndex];
        const characterIndex = part.character_index ?? 1;
        const character = characterData[characterIndex - 1];
        return {
          index: part.index ?? partIndex + 1,
          character_index: characterIndex,
          index_in_character: part.index_in_character ?? 1,
          line_index: character.line_index ?? 1,
          text: character.text ?? "",
          path: {
            svg: scaleSvgPathNumbers(
              flatPartGeometry[partIndex]?.pathData ?? "",
              normalizedUnitsPerEm / pathFontSize,
            ),
            units_per_em: normalizedUnitsPerEm,
          },
        };
      }),
    };
    const pathEvaluation =
      baseEvaluation.succeeded && layoutEvaluation.succeeded
        ? this.scriptPipeline.evaluatePaths(pathHookData, frameSeed(frame, 3))
        : { data: pathHookData, succeeded: true, errors: [], warnings: [] };
    errors.push(...pathEvaluation.errors);
    warnings.push(...pathEvaluation.warnings);
    const pathOverrides = new Map(
      pathEvaluation.data.path_parts
        .filter((part) => part.edited === true)
        .map((part) => [part.index - 1, editedPathToPixels(part.path, pathFontSize)]),
    );
    const finalShapePaths = layoutShapePaths.map((layoutPath, shapeIndex) => {
      const record = pathEvaluation.data.shape_parts?.[shapeIndex];
      return record?.edited === true ? editedPathToPixels(record.path, pathFontSize) : layoutPath;
    });

    const scriptOutputCharacters = naturalCharacters.map(
      (_, index) => resolvedCharacters[index] ?? characterData[index],
    );
    const scriptOutputParts = partData.map(
      (input, index) => resolvedParts[index] ?? input,
    );
    const effectiveCharacters = naturalCharacters.map((_, index) =>
      resolveEffectiveCharacter(scriptOutputCharacters[index], resolvedGlobal),
    );

    const globalTransform = globalMatrix(resolvedGlobal, canvasWidth, canvasHeight);
    // The shadow keeps its distance to the glyph in the glyph's own space, in a direction fixed on the
    // canvas: the unscaled offset is stretched by how far one local unit reaches along that direction.
    const baseShadowOffset = shadowOffsetPixels(
      resolvedGlobal.shadow.distance,
      resolvedGlobal.shadow.angle,
      fontSizePixels(canvasHeight),
    );
    const shadowDirection = {
      x: Math.cos((resolvedGlobal.shadow.angle * Math.PI) / 180),
      y: Math.sin((resolvedGlobal.shadow.angle * Math.PI) / 180),
    };
    const shadowOffsetFor = (jacobian: Jacobian2D): { x: number; y: number } => {
      const scale = shadowDistanceScale(jacobian, shadowDirection);
      return { x: baseShadowOffset.x * scale, y: baseShadowOffset.y * scale };
    };
    // A blur is given in em; how far one local pixel reaches along each canvas axis carries it to
    // canvas pixels.
    const fontSize = fontSizePixels(canvasHeight);
    const blurFor = (amountEm: number, axis: { x: number; y: number }, jacobian: Jacobian2D): number =>
      quantizeBlurSigma(amountEm * fontSize * shadowDistanceScale(jacobian, axis));
    const kAxisX = { x: 1, y: 0 };
    const kAxisY = { x: 0, y: 1 };
    // The frame-level offset, used by what is not one part's own, follows the global transform alone.
    const globalJacobian: Jacobian2D = {
      dxdx: globalTransform.a,
      dxdy: globalTransform.c,
      dydx: globalTransform.b,
      dydy: globalTransform.d,
    };
    const shadowOffset = shadowOffsetFor(globalJacobian);
    const projector = projection3DEnabled
      ? new Projection3DProjector(canvasWidth, canvasHeight, resolvedGlobal, resolvedCamera)
      : undefined;
    const frameTexture = globalTexture(resolvedGlobal.texture);
    const characters: EvaluatedBox[] = [];
    const parts: EvaluatedBox[] = [];
    const effectiveParts: CtxPartData[] = [];
    let flatPartIndex = 0;
    for (const [index, natural] of naturalCharacters.entries()) {
      const character = effectiveCharacters[index];
      const characterTexture = resolveTexture(frameTexture, character.texture);
      const characterTransform = multiply(
        globalTransform,
        characterMatrix(character, natural, canvasWidth, canvasHeight),
      );
      const projectedCharacterCenter = projector?.projectCharacterCenter(natural, character);
      const isSpaceCharacter =
        natural.pathData === undefined && natural.text.trim().length === 0;
      characters.push({
        index: index + 1,
        centerX: natural.centerX,
        centerY: natural.centerY,
        width: natural.width,
        height: natural.height,
        matrix: characterTransform,
        fillColor: character.fill.color,
        opacity: character.opacity,
        useGradientFill: !character.fill.use,
        fillVisible: !resolvedGlobal.fill.transparent || character.fill.use,
        texture: characterTexture,
        strokeWidth: character.stroke.width,
        strokeGap: character.stroke.gap,
        strokeColor: character.stroke.color,
        outerStrokeWidth: character.stroke.outer_width,
        outerStrokeColor: character.stroke.outer_color,
        shadowColor: character.shadow.color,
        hasIndividualShadow: character.shadow.use,
        characterIndex: index + 1,
        text: natural.text,
        pathData: natural.pathData,
        originX: natural.centerX,
        originY: natural.centerY,
        projectionDepth: projectedCharacterCenter?.depth,
        projectedCenterX: projectedCharacterCenter?.x,
        projectedCenterY: projectedCharacterCenter?.y,
      });
      for (const geometry of partGeometry[index]) {
        const partOutput = scriptOutputParts[flatPartIndex];
        const part = resolveEffectivePart(partOutput, character);
        const scriptedPathData = pathOverrides.get(flatPartIndex);
        const drawableGeometry =
          scriptedPathData === undefined ? geometry : { ...geometry, pathData: scriptedPathData };
        const projectedGeometry = projector?.projectPart(natural, drawableGeometry, character, part);
        // A script that returns a path replaces the glyph, and its outline groups with it.
        const strokeOutlines = scriptedPathData === undefined ? geometry.strokeOutlines : undefined;
        const isStroked = part.stroke.width > 0;
        const projectedStrokeOutlines = projector !== undefined && strokeOutlines !== undefined && isStroked
          ? strokeOutlines.map((outline) =>
            projector.projectPart(natural, { ...drawableGeometry, pathData: outline }, character, part).pathData ?? "")
          : undefined;
        // Part paths are character-center-relative and translated to the
        // character's natural center by the renderer. Therefore the
        // matrix pivot lives at the absolute part BB center in the same
        // pre-character canvas space.
        const partTransform = multiply(
          characterTransform,
          partMatrix(part, geometry.centerX, geometry.centerY, canvasWidth, canvasHeight),
        );
        const partJacobian: Jacobian2D = projector?.projectPartJacobian(
          natural,
          drawableGeometry,
          character,
          part,
        ) ?? {
          dxdx: partTransform.a,
          dxdy: partTransform.c,
          dydx: partTransform.b,
          dydy: partTransform.d,
        };
        const partShadowOffset = shadowOffsetFor(partJacobian);
        effectiveParts.push(part);
        parts.push({
          index: flatPartIndex + 1,
          shadowOffsetX: partShadowOffset.x,
          shadowOffsetY: partShadowOffset.y,
          blurX: blurFor(part.blur.amount_x, kAxisX, partJacobian),
          blurY: blurFor(part.blur.amount_y, kAxisY, partJacobian),
          shadowBlurX: blurFor(part.shadow.blur_x, kAxisX, partJacobian),
          shadowBlurY: blurFor(part.shadow.blur_y, kAxisY, partJacobian),
          shadowGlowGain: resolveGlowGain(part.shadow.glow),
          blurGlowGain: resolveGlowGain(part.blur.glow),
          centerX: geometry.centerX,
          centerY: geometry.centerY,
          width: geometry.width,
          height: geometry.height,
          matrix: partTransform,
          fillColor: part.fill.color,
          opacity: part.opacity,
          useGradientFill: !character.fill.use && !part.fill.use,
          fillVisible: !resolvedGlobal.fill.transparent || character.fill.use || part.fill.use,
          texture: resolveTexture(characterTexture, part.texture),
          strokeWidth: part.stroke.width,
          strokeGap: part.stroke.gap,
          strokeColor: part.stroke.color,
          outerStrokeWidth: part.stroke.outer_width,
          outerStrokeColor: part.stroke.outer_color,
          shadowColor: part.shadow.color,
          hasIndividualShadow: part.shadow.use,
          characterIndex: index + 1,
          isSpace: isSpaceCharacter,
          pathData: drawableGeometry.pathData,
          strokeOutlines,
          // Glyph outlines are stored relative to the character origin, but a
          // script-supplied path is drawn around the part's own origin.
          originX: scriptedPathData === undefined ? natural.centerX : geometry.originX,
          originY: scriptedPathData === undefined ? natural.centerY : geometry.originY,
          clipRect: geometry.clipRect,
          // A path a script returns replaces the emoji, as it turns the host's emoji part into an ordinary one.
          emoji: scriptedPathData === undefined ? geometry.emoji : undefined,
          projectedPathData: projectedGeometry?.pathData,
          projectedClipPathData: projectedGeometry?.clipPathData,
          projectedBoxPathData: projectedGeometry?.boxPathData,
          projectedStrokeOutlines,
          projectionDepth: projectedCharacterCenter?.depth ?? projectedGeometry?.depth,
        });
        flatPartIndex += 1;
      }
    }

    const shapes: EvaluatedBox[] = [];
    const restingGlobalTransform = globalMatrix(
      globalToCtx(createDefaultScene().global),
      canvasWidth,
      canvasHeight,
    );
    // The matrix of each shape so far: a child is placed under its parent's, which is declared before it.
    const shapeCharacterMatrices: ReturnType<typeof multiply>[] = [];
    // Where each shape under a camera lands on the canvas plane, and the projector of those cameras.
    const shapePlaces: (ShapePlace | undefined)[] = [];
    const shapeProjector = shapeDeclarations.some((declaration) => (declaration.camera ?? 0) > 0)
      ? new ShapeCameraProjector(canvasWidth, canvasHeight, resolvedShapeCameras, defaultShapeCamera)
      : undefined;
    for (const [shapeIndex, declaration] of shapeDeclarations.entries()) {
      const shape = resolveEffectiveCharacter(resolvedShapes[shapeIndex] ?? shapeData[shapeIndex], resolvedGlobal);
      const shapePart = resolveEffectivePart(
        partSceneToCtx(createDefaultPartScene(), resolvedGlobalScene),
        shape,
      );
      const pathData = finalShapePaths[shapeIndex];
      const bounds = pathBounds(pathData) ?? { centerX: 0, centerY: 0, width: 0, height: 0 };
      const natural = shapeNaturalCharacter(bounds);
      const parentMatrix =
        declaration.parent > 0 ? shapeCharacterMatrices[declaration.parent - 1] : restingGlobalTransform;
      const shapeCharacterMatrix = multiply(parentMatrix, characterMatrix(shape, natural, canvasWidth, canvasHeight));
      shapeCharacterMatrices.push(shapeCharacterMatrix);
      const partTransform = multiply(shapeCharacterMatrix, partMatrix(shapePart, 0, 0, canvasWidth, canvasHeight));
      // A shape under a camera is projected through its own place and that camera instead of the matrix.
      const cameraNumber = declaration.camera ?? 0;
      let projectedShape: ProjectedShape | undefined;
      if (shapeProjector !== undefined && cameraNumber > 0) {
        const place = shapePlaceOf(
          shape,
          declaration.parent > 0 ? shapePlaces[declaration.parent - 1] : undefined,
          canvasWidth,
          canvasHeight,
        );
        shapePlaces.push(place);
        projectedShape = shapeProjector.projectShape(place, cameraNumber, pathData, bounds);
      } else {
        shapePlaces.push(undefined);
      }
      const jacobian: Jacobian2D = projectedShape?.jacobian ?? {
        dxdx: partTransform.a,
        dxdy: partTransform.c,
        dydx: partTransform.b,
        dydy: partTransform.d,
      };
      const shadowOffsetOfShape = shadowOffsetFor(jacobian);
      shapes.push({
        index: shapeIndex + 1,
        shadowOffsetX: shadowOffsetOfShape.x,
        shadowOffsetY: shadowOffsetOfShape.y,
        blurX: blurFor(shapePart.blur.amount_x, kAxisX, jacobian),
        blurY: blurFor(shapePart.blur.amount_y, kAxisY, jacobian),
        shadowBlurX: blurFor(shapePart.shadow.blur_x, kAxisX, jacobian),
        shadowBlurY: blurFor(shapePart.shadow.blur_y, kAxisY, jacobian),
        shadowGlowGain: resolveGlowGain(shapePart.shadow.glow),
        blurGlowGain: resolveGlowGain(shapePart.blur.glow),
        centerX: bounds.centerX,
        centerY: bounds.centerY,
        width: bounds.width,
        height: bounds.height,
        matrix: partTransform,
        fillColor: shapePart.fill.color,
        opacity: shapePart.opacity,
        // The gradient spans the text, so a shape keeps its plain fill.
        useGradientFill: false,
        fillVisible: !resolvedGlobal.fill.transparent || shape.fill.use || shapePart.fill.use,
        texture: resolveTexture(resolveTexture(frameTexture, shape.texture), shapePart.texture),
        strokeWidth: shapePart.stroke.width,
        strokeGap: shapePart.stroke.gap,
        strokeColor: shapePart.stroke.color,
        outerStrokeWidth: shapePart.stroke.outer_width,
        outerStrokeColor: shapePart.stroke.outer_color,
        shadowColor: shapePart.shadow.color,
        hasIndividualShadow: shapePart.shadow.use,
        characterIndex: shapeIndex + 1,
        shapeLayer: declaration.layer,
        shapeZIndex: shape.z_index ?? 0,
        shapeCamera: cameraNumber,
        projectedPathData: projectedShape?.pathData,
        projectedBoxPathData: projectedShape?.boxPathData,
        projectionDepth: projectedShape?.depth,
        pathData,
        originX: 0,
        originY: 0,
      });
    }

    const result: EvaluatedFrame & { shapes: EvaluatedBox[] } = {
      frame,
      time,
      canvasWidth,
      canvasHeight,
      backgroundColor: cloneColor(scene.settings.backgroundColor),
      checkerboardBackground: scene.settings.checkerboardBackground,
      showSpaces: scene.settings.showSpaces,
      spaceColor: cloneColor(scene.settings.spaceColor),
      shadowEnabled: resolvedGlobal.shadow.enabled,
      shadowOffsetX: shadowOffset.x,
      shadowOffsetY: shadowOffset.y,
      gradient: {
        enabled: resolvedGlobal.gradient.color_space !== "none",
        startColor: cloneColor(resolvedGlobal.fill.color),
        endColor: cloneColor(resolvedGlobal.gradient.end_color),
        midpoint: resolvedGlobal.gradient.midpoint,
        angle: resolvedGlobal.gradient.angle,
        start: resolvedGlobal.gradient.start_position,
        end: resolvedGlobal.gradient.end_position,
      },
      projection3D: projection3DEnabled,
      characters,
      parts,
      shapes,
      scriptInputValues: {
        global: globalToCtx(baseGlobal),
        camera: cameraToCtx(scene.camera),
        characters: characterData,
        parts: partData,
        boundingBox: boundingBoxToCtx(scene.boundingBox),
        output: outputToCtx(scene.output),
      },
      scriptOutputValues: {
        global: resolvedGlobal,
        camera: resolvedCamera,
        characters: scriptOutputCharacters,
        parts: scriptOutputParts,
        boundingBox: resolvedBoundingBox,
        output: resolvedOutput,
      },
      requestedFontName,
      errors,
      warnings,
    };
    this.sceneGeometry.setLayoutEngine(this.selectedLayoutEngine);
    return result;
  }

}

function alignNaturalCharacters(characters: NaturalCharacter[], global: GlobalScene): void {
  let minimumX = Infinity;
  let minimumY = Infinity;
  let maximumX = -Infinity;
  let maximumY = -Infinity;
  for (const character of characters) {
    let centerX = character.boundingCenterX;
    let centerY = character.boundingCenterY;
    let width = character.width;
    let height = character.height;
    if (!character.customGlyph && character.pathData !== undefined) {
      const bounds = pathBounds(character.pathData);
      if (bounds === undefined) continue;
      centerX = character.centerX + bounds.centerX;
      centerY = character.centerY + bounds.centerY;
      width = bounds.width;
      height = bounds.height;
    } else if (!character.customGlyph && character.text.trim().length === 0) {
      continue;
    }
    // Empty declared bounds opt out even when the glyph has a visible path.
    if (width <= 0 && height <= 0) continue;
    minimumX = Math.min(minimumX, centerX - width / 2);
    maximumX = Math.max(maximumX, centerX + width / 2);
    minimumY = Math.min(minimumY, centerY - height / 2);
    maximumY = Math.max(maximumY, centerY + height / 2);
  }
  if (minimumX !== Infinity) {
    const deltaX = -minimumX + alignmentOffset(global.hAlign, maximumX - minimumX);
    let deltaY = 0;
    if (global.vAlign !== "baseline" || global.vertical) {
      const alignment = global.vAlign === "baseline" ? "center" : verticalAlignment(global.vAlign);
      deltaY = -minimumY + alignmentOffset(alignment, maximumY - minimumY);
    }
    for (const character of characters) {
      shiftNaturalCharacter(character, deltaX, deltaY);
    }
  }
}

function cloneColor(color: Rgba): Rgba {
  return { r: color.r, g: color.g, b: color.b, a: color.a };
}

function applyGlyphDeclarations(
  characters: NaturalCharacter[],
  declarations: readonly GlyphDeclarationData[],
  global: GlobalScene,
  fontSize: number,
): void {
  const declarationsByMarker = new Map(declarations.map((declaration) => [
    declaration.marker,
    declaration,
  ]));
  const lineDeltas = new Map<number, number>();
  for (const [characterIndex, character] of characters.entries()) {
    const declaration = declarationsByMarker.get(character.text);
    if (declaration !== undefined) {
      const spacing = (global.tracking + (global.margins[characterIndex] ?? 0)) * fontSize;
      const oldAdvance = (global.vertical ? character.advanceY : character.advanceX) + spacing;
      const newAdvance =
        (global.vertical ? -declaration.advance_y : declaration.advance_x) * fontSize / 1000 + spacing;
      lineDeltas.set(character.lineIndex, (lineDeltas.get(character.lineIndex) ?? 0) + newAdvance - oldAdvance);
    }
  }

  const accumulatedDeltas = new Map<number, number>();
  for (const [characterIndex, character] of characters.entries()) {
    const lineDelta = lineDeltas.get(character.lineIndex) ?? 0;
    const alignmentDelta = global.vertical
      ? alignmentOffset(verticalAlignment(global.vAlign), lineDelta)
      : alignmentOffset(global.hAlign, lineDelta);
    const precedingDelta = accumulatedDeltas.get(character.lineIndex) ?? 0;
    const positionDelta = alignmentDelta + precedingDelta;
    if (global.vertical) {
      shiftNaturalCharacter(character, 0, positionDelta);
    } else {
      shiftNaturalCharacter(character, positionDelta, 0);
    }

    const declaration = declarationsByMarker.get(character.text);
    if (declaration !== undefined) {
      const spacing = (global.tracking + (global.margins[characterIndex] ?? 0)) * fontSize;
      const oldAdvance = (global.vertical ? character.advanceY : character.advanceX) + spacing;
      const newAdvanceX = declaration.advance_x * fontSize / 1000;
      const newAdvanceY = -declaration.advance_y * fontSize / 1000;
      const newAdvance = (global.vertical ? newAdvanceY : newAdvanceX) + spacing;
      accumulatedDeltas.set(character.lineIndex, precedingDelta + newAdvance - oldAdvance);
      applyDeclaredGlyphGeometry(character, declaration, fontSize);
      character.advanceX = newAdvanceX;
      character.advanceY = newAdvanceY;
    }
  }
}

function applyDeclaredGlyphGeometry(
  character: NaturalCharacter,
  declaration: GlyphDeclarationData,
  fontSize: number,
): void {
  const normalizedScale = fontSize / 1000;
  const normalizedPathData = normalizedDeclaredGlyphPath(declaration);
  let resolvedBounds = declaration.bounds;
  let partPositionX = 0;
  let partPositionY = 0;
  if (resolvedBounds === undefined && normalizedPathData !== undefined) {
    const geometry = pathBounds(normalizedPathData);
    if (geometry !== undefined) {
      partPositionX = declaration.advance_x * 0.5;
      const pathMinimumX = geometry.centerX - geometry.width * 0.5;
      const pathMinimumY = geometry.centerY - geometry.height * 0.5;
      const pathMaximumX = geometry.centerX + geometry.width * 0.5;
      const pathMaximumY = geometry.centerY + geometry.height * 0.5;
      partPositionY = -pathMaximumY;
      resolvedBounds = [
        partPositionX + pathMinimumX,
        0,
        partPositionX + pathMaximumX,
        pathMaximumY - pathMinimumY,
      ];
    }
  } else if (resolvedBounds !== undefined) {
    partPositionX = (resolvedBounds[0] + resolvedBounds[2]) * 0.5;
    partPositionY = -(resolvedBounds[1] + resolvedBounds[3]) * 0.5;
  }
  resolvedBounds ??= [0, 0, 0, 0];
  const [minimumX, minimumY, maximumX, maximumY] = resolvedBounds;
  character.centerX = character.originX + partPositionX * normalizedScale;
  character.centerY = character.originY + partPositionY * normalizedScale;
  character.boundingCenterX = character.originX + (minimumX + maximumX) * 0.5 * normalizedScale;
  character.boundingCenterY = character.originY - (minimumY + maximumY) * 0.5 * normalizedScale;
  character.width = (maximumX - minimumX) * normalizedScale;
  character.height = (maximumY - minimumY) * normalizedScale;
  character.customGlyph = true;
  character.emoji = undefined;
  character.pathData = normalizedPathData === undefined
    ? undefined
    : scaleSvgPathNumbers(normalizedPathData, normalizedScale);
}

function normalizedDeclaredGlyphPath(declaration: GlyphDeclarationData): string | undefined {
  return normalizedDeclaredPath(declaration.path);
}

// A declared path in the normalized 1000 units per em.
function normalizedDeclaredPath(path: GlyphDeclarationData["path"]): string | undefined {
  let result: string | undefined;
  if (path !== undefined) {
    result = path.view_box === undefined
      ? scaleSvgPathNumbers(path.svg, kNormalizedUnitsPerEm / path.units_per_em)
      : normalizeSvgPathViewBox(path.svg, path.view_box, kNormalizedUnitsPerEm, path.em_scale ?? 1);
  }
  return result;
}

// A path a script returned, back in canvas pixels around the part's own origin.
function editedPathToPixels(path: NonNullable<GlyphDeclarationData["path"]>, fontSize: number): string {
  return path.view_box === undefined
    ? scaleSvgPathNumbers(path.svg, fontSize / path.units_per_em)
    : scaleSvgPathNumbers(
      normalizeSvgPathViewBox(path.svg, path.view_box, kNormalizedUnitsPerEm, path.em_scale ?? 1),
      fontSize / kNormalizedUnitsPerEm,
    );
}

// The shape's path is drawn around its own position, which is also where it rests on the canvas.
function shapeNaturalCharacter(bounds: { centerX: number; centerY: number; width: number; height: number }): NaturalCharacter {
  return {
    text: "",
    lineIndex: 0,
    originX: 0,
    originY: 0,
    verticalOriginX: 0,
    verticalOriginY: 0,
    advanceX: 0,
    advanceY: 0,
    centerX: bounds.centerX,
    centerY: bounds.centerY,
    width: bounds.width,
    height: bounds.height,
    // A shape turns and scales about its position, not about the middle of its outline.
    boundingCenterX: 0,
    boundingCenterY: 0,
  };
}

function shiftNaturalCharacter(character: NaturalCharacter, deltaX: number, deltaY: number): void {
  character.originX += deltaX;
  character.originY += deltaY;
  character.verticalOriginX += deltaX;
  character.verticalOriginY += deltaY;
  character.centerX += deltaX;
  character.centerY += deltaY;
  character.boundingCenterX += deltaX;
  character.boundingCenterY += deltaY;
}

function alignmentOffset(alignment: "left" | "center" | "right", extentDelta: number): number {
  let result = -extentDelta * 0.5;
  if (alignment === "left") {
    result = 0;
  } else if (alignment === "right") {
    result = -extentDelta;
  }
  return result;
}

function verticalAlignment(
  alignment: "top" | "center" | "bottom" | "baseline",
): "left" | "center" | "right" {
  let result: "left" | "center" | "right" = "center";
  if (alignment === "top" || alignment === "baseline") {
    result = "left";
  } else if (alignment === "bottom") {
    result = "right";
  }
  return result;
}

function scaleSvgPathNumbers(pathData: string, scale: number): string {
  const numberPattern = /[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/g;
  return pathData.replace(
    numberPattern,
    (value) => String(Number((Number(value) * scale).toPrecision(12))),
  );
}

// Mirrors readSvgPathNormalization in ScriptPathBindings.cc: the view box is centred on the origin
// and its longest side maps to em_scale ems, so em_scale 1.0 fills exactly one em.
function normalizeSvgPathViewBox(
  pathData: string,
  viewBox: number[],
  normalizedSize: number,
  emScale: number,
): string {
  const [minimumX, minimumY, width, height] = viewBox;
  const centerX = minimumX + width * 0.5;
  const centerY = minimumY + height * 0.5;
  const scale = (normalizedSize * emScale) / Math.max(width, height);
  const commandPattern = /([MmLlHhVvQqTtCcSsZz])([^MmLlHhVvQqTtCcSsZz]*)/g;
  const numberPattern = /[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/g;
  let firstCommand = true;
  return [...pathData.matchAll(commandPattern)].map((match) => {
    const command = match[1];
    const values = (match[2].match(numberPattern) ?? []).map(Number);
    const absolute = command === command.toUpperCase();
    const horizontal = command.toUpperCase() === "H";
    const vertical = command.toUpperCase() === "V";
    const transformed = values.map((value, index) => {
      let result = value * scale;
      if (absolute || (firstCommand && command === "m" && index < 2)) {
        const coordinateCenter = horizontal || (!vertical && index % 2 === 0) ? centerX : centerY;
        result = (value - coordinateCenter) * scale;
      }
      return String(Number(result.toPrecision(12)));
    });
    firstCommand = false;
    return command + (transformed.length > 0 ? ` ${transformed.join(" ")}` : "");
  }).join(" ");
}
