import { FrameEvaluator, type EvaluatedFrame } from "../../core/frameEvaluator";
import { TextLayoutEngine, type HarfBuzzApi } from "../../core/layout";
import { ScriptEngine } from "../../core/luaEngine";
import { parseMugMetadata } from "../../shared/luaCompletionContext";
import { applyMetadataToScene, createDefaultScene } from "../../shared/sceneSchema";
import { bundledFontEntries, chooseBundledFontForLanguage, loadFontBytes } from "./fontSources";
import { loadSampleSource, type SampleEntry } from "./sampleCatalog";

export interface SamplePreviewRuntime {
  fps: number;
  durationFrames: number;
  evaluate: (frame: number) => EvaluatedFrame;
  dispose: () => void;
}

export type SamplePreviewRuntimeFactory = (sample: SampleEntry) => Promise<SamplePreviewRuntime>;

export interface SamplePreviewAssets {
  preludeSource: string;
  wasmUri?: string;
  fonts: readonly { family: string; layoutEngine: TextLayoutEngine }[];
}

export async function createSamplePreviewRuntime(
  source: string,
  assets: SamplePreviewAssets,
): Promise<SamplePreviewRuntime> {
  const scene = createDefaultScene();
  const metadata = parseMugMetadata(source);
  applyMetadataToScene(scene, metadata);
  const preferredFamily = chooseBundledFontForLanguage(metadata.fontLang)?.family;
  const selectedFont = assets.fonts.find((font) => font.family === preferredFamily) ?? assets.fonts[0];
  const layoutEngine = selectedFont?.layoutEngine;
  const engine = await ScriptEngine.create({
    wasmUri: assets.wasmUri,
    preludeSource: assets.preludeSource,
    log: () => {},
  });
  try {
    const loaded = await engine.loadScript(source);
    if (!loaded.ok) throw new Error(loaded.message ?? "Failed to load sample");
    const evaluator = new FrameEvaluator(engine);
    evaluator.setFontNames(assets.fonts.map((font) => font.family));
    for (const font of assets.fonts) evaluator.registerLayoutEngine(font.layoutEngine, font.family);
    evaluator.setLayoutEngine(layoutEngine);
    if (layoutEngine !== undefined) scene.global.fontName = layoutEngine.familyName();
    evaluator.synchronizeSceneTopology(scene);
    const initialized = evaluator.initialize(scene);
    if (initialized.errors.length > 0) throw new Error(initialized.errors[0]);
    return {
      fps: scene.settings.fps,
      durationFrames: scene.settings.durationFrames,
      evaluate: (frame) => {
        const result = evaluator.evaluate(scene, frame);
        if (result.errors.length > 0) throw new Error(result.errors[0]);
        return result;
      },
      dispose: () => engine.dispose(),
    };
  } catch (error) {
    engine.dispose();
    throw error;
  }
}

export function createSamplePreviewRuntimeFactory(options: {
  preludeSource: string;
  wasmUri: string;
  hbModuleUri: string;
}): SamplePreviewRuntimeFactory {
  // HarfBuzz layout objects cache outlines and belong to the browser previews, not the editor.
  let assetsPromise: Promise<SamplePreviewAssets> | undefined;
  function assets(): Promise<SamplePreviewAssets> {
    assetsPromise ??= Promise.all([
      import(/* @vite-ignore */ options.hbModuleUri) as Promise<HarfBuzzApi>,
      Promise.all(bundledFontEntries.map(async (font) => ({ family: font.family, bytes: await loadFontBytes(font.path) }))),
    ]).then(([harfBuzz, fonts]) => ({
      preludeSource: options.preludeSource,
      wasmUri: options.wasmUri,
      fonts: fonts.map((font) => ({ family: font.family, layoutEngine: new TextLayoutEngine(harfBuzz, font.bytes) })),
    })).catch((error: unknown) => {
      assetsPromise = undefined;
      throw error;
    });
    return assetsPromise;
  }
  return async (sample) => {
    const [source, loadedAssets] = await Promise.all([loadSampleSource(sample), assets()]);
    return createSamplePreviewRuntime(source, loadedAssets);
  };
}
