import { onLocaleChange, t } from "../../shared/i18n";

// The "mt-web-" prefix is what "Clear Local Data" removes (see clearAllStoredData).
const kStorageKey = "mt-web-tutorial-seen-v1";
const kTutorialSampleId = "showcase/PRT019_part_swirl.lua";
const kSteps = [
  { id: "intro", target: "", action: "confirm" },
  { id: "menu", target: "#app-menu-button", action: "click" },
  { id: "samples", target: "#open-sample-browser-button", action: "click" },
  { id: "showcase", target: '[data-genre-id="showcase"] > summary > button', action: "click" },
  { id: "basic", target: '[data-genre-id="showcase/basic"] > summary > button', action: "click" },
  { id: "parts", target: '[data-genre-id="showcase/basic/parts"] > summary > button', action: "click" },
  { id: "leaf", target: `.sample-tree-leaf[data-sample-id="${kTutorialSampleId}"]`, action: "click" },
  { id: "samplePreview", target: `.sample-card[data-sample-id="${kTutorialSampleId}"] .sample-live-preview`, action: "watch" },
  { id: "select", target: `.sample-card[data-sample-id="${kTutorialSampleId}"] .sample-card-open`, action: "load" },
  { id: "edit", target: "#lua-editor", action: "confirm" },
  { id: "play", target: ".timeline > button", action: "watch" },
  { id: "copy", target: ".toolbar-copy-script-button", action: "copy" },
  { id: "resolve", target: "", action: "confirm" },
  { id: "resolvePage", target: "", action: "confirm" },
  { id: "resolvePaste", target: "", action: "confirm" },
] as const;
const kBrowsingSteps: string[] = ["showcase", "basic", "parts", "leaf", "samplePreview", "select"];
// Screenshots from the user manual, copied to web-dist/tutorial/ by esbuild.web.mjs.
// Rings mark the controls to use, as percentages of the 615x500 screenshot.
const kStepImages: Record<string, { src: string; width: number; height: number; alt: Parameters<typeof t>[0]; rings?: { left: number; top: number; width: number; height: number }[] }> = {
  resolve: { alt: "tutorial.resolve.alt", src: "tutorial/resolve_effect_library_presets.webp", width: 754, height: 685, rings: [{ left: 31, top: 72.2, width: 66.4, height: 8 }] },
  resolvePage: { alt: "tutorial.resolvePage.alt", src: "tutorial/inspector_scripting_standard.webp", width: 615, height: 500, rings: [{ left: 32.5, top: 25, width: 48.5, height: 7.5 }] },
  resolvePaste: { alt: "tutorial.resolvePaste.alt", src: "tutorial/inspector_scripting_standard.webp", width: 615, height: 500, rings: [
    { left: 32.5, top: 50.5, width: 28, height: 7.5 },
    { left: 32.5, top: 90.5, width: 23.5, height: 8 },
  ] },
};

export function mountTutorial(): { start: () => void; dispose: () => void } {
  let stepIndex = 0;
  let card: HTMLElement | undefined;
  let highlight: HTMLElement | undefined;
  let ring: HTMLElement | undefined;
  let shades: HTMLElement[] = [];
  let previousFocus: HTMLElement | undefined;
  let animationFrame = 0;
  let disposed = false;
  let generation = 0;
  let watchStarted = false;
  let restoring = false;
  // Kept referenced so the screenshots are decoded before their steps appear.
  const preloadedImages = [...new Set(Object.values(kStepImages).map((image) => image.src))].map((src) => {
    const picture = document.createElement("img");
    picture.src = src;
    return picture;
  });

  function target(): HTMLElement | null {
    const selector = kSteps[stepIndex].target;
    return selector ? document.querySelector<HTMLElement>(selector) : null;
  }

  function browsingSamples(): boolean {
    return kBrowsingSteps.includes(kSteps[stepIndex].id);
  }

  function remove(): void {
    generation++;
    cancelAnimationFrame(animationFrame);
    card?.remove();
    highlight?.remove();
    ring?.remove();
    shades.forEach((shade) => shade.remove());
    shades = [];
    card = undefined;
    highlight = undefined;
    ring = undefined;
    document.body.classList.remove("tutorial-select");
    document.body.style.removeProperty("--tutorial-sample-reserve");
  }

  function finish(): void {
    try { localStorage.setItem(kStorageKey, "true"); } catch { /* Storage can be disabled. */ }
    remove();
    if (previousFocus?.isConnected) previousFocus.focus();
  }

  function place(element: HTMLElement, left: number, top: number, width: number, height: number): void {
    Object.assign(element.style, {
      left: `${left}px`, top: `${top}px`, width: `${Math.max(0, width)}px`, height: `${Math.max(0, height)}px`,
    });
  }

  function position(): void {
    if (!card || !highlight || !ring) return;
    const width = window.innerWidth;
    const height = window.innerHeight;
    const margin = 12;
    const gap = 16;
    const padding = 5;
    const cardWidth = card.getBoundingClientRect().width;
    const cardHeight = card.getBoundingClientRect().height;
    const selectingSample = browsingSamples();
    if (selectingSample) {
      document.body.style.setProperty("--tutorial-sample-reserve", `${cardHeight + margin * 2 + gap + padding}px`);
    } else {
      document.body.style.removeProperty("--tutorial-sample-reserve");
    }
    const targetBounds = target()?.getBoundingClientRect();
    let spotlightBounds = targetBounds;
    const companionSelector = { play: ".preview-area", samples: "#app-menu" }[kSteps[stepIndex].id as string];
    if (companionSelector && spotlightBounds) {
      const companion = document.querySelector(companionSelector)?.getBoundingClientRect();
      if (companion && companion.width > 0 && companion.height > 0) {
        const left = Math.min(spotlightBounds.left, companion.left);
        const top = Math.min(spotlightBounds.top, companion.top);
        const right = Math.max(spotlightBounds.right, companion.right);
        const bottom = Math.max(spotlightBounds.bottom, companion.bottom);
        spotlightBounds = { left, top, right, bottom, width: right - left, height: bottom - top } as DOMRect;
      }
    }
    const bounds = spotlightBounds;
    const visible = bounds && bounds.width > 0 && bounds.height > 0 && bounds.bottom > 0 && bounds.right > 0 && bounds.top < height && bounds.left < width;
    const left = visible ? Math.max(0, bounds.left - padding) : 0;
    const top = visible ? Math.max(0, bounds.top - padding) : 0;
    const right = visible ? Math.min(width, bounds.right + padding) : 0;
    const bottom = visible ? Math.min(height, bounds.bottom + padding) : 0;
    highlight.hidden = !visible;
    highlight.classList.toggle("tutorial-highlight-clear", kSteps[stepIndex].id === "samples");
    place(highlight, left, top, right - left, bottom - top);
    const ringed = visible && companionSelector !== undefined && targetBounds !== undefined && targetBounds.width > 0 && targetBounds.height > 0;
    ring.hidden = !ringed;
    if (ringed) place(ring, targetBounds.left - padding, targetBounds.top - padding, targetBounds.width + padding * 2, targetBounds.height + padding * 2);
    place(shades[0], 0, 0, width, top);
    place(shades[1], 0, top, left, bottom - top);
    place(shades[2], right, top, width - right, bottom - top);
    place(shades[3], 0, bottom, width, height - bottom);

    let x = (width - cardWidth) / 2;
    let y = (height - cardHeight) / 2;
    let side = "center";
    if (selectingSample) {
      y = height - cardHeight - margin;
      side = "bottom";
    } else if (visible) {
      if (width - right >= cardWidth + gap + margin) {
        x = right + gap; y = top; side = "right";
      } else if (left >= cardWidth + gap + margin) {
        x = left - cardWidth - gap; y = top; side = "left";
      } else if (height - bottom >= cardHeight + gap + margin) {
        x = left; y = bottom + gap; side = "bottom";
      } else {
        x = left; y = top - cardHeight - gap; side = "top";
      }
    }
    card.dataset.side = side;
    card.style.left = `${Math.max(margin, Math.min(x, width - cardWidth - margin))}px`;
    card.style.top = `${Math.max(margin, Math.min(y, height - cardHeight - margin))}px`;
  }

  function trackTarget(): void {
    position();
    animationFrame = requestAnimationFrame(trackTarget);
  }

  function enterStep(): void {
    watchStarted = false;
    if (kSteps[stepIndex].id === "showcase") {
      const search = document.querySelector<HTMLInputElement>("#sample-browser-search");
      if (search) {
        search.value = "";
        search.dispatchEvent(new Event("input", { bubbles: true }));
      }
    }
    render();
    target()?.scrollIntoView?.({ block: "nearest", inline: "nearest" });
    (target()?.querySelector<HTMLElement>('button, input, textarea, [tabindex="0"]') ?? target() ?? card)?.focus();
  }

  function advance(): void {
    if (!card) return;
    if (stepIndex === kSteps.length - 1) finish();
    else {
      stepIndex++;
      enterStep();
    }
  }

  // Puts the menu and the sample browser back into the state the step expects,
  // using the app's own buttons so its handlers keep their bookkeeping.
  function restoreUi(id: string): void {
    const press = (selector: string): void => {
      restoring = true;
      try { document.querySelector<HTMLElement>(selector)?.click(); } finally { restoring = false; }
    };
    const browserOpen = document.querySelector("#sample-browser-overlay.visible") !== null;
    const menuOpen = document.querySelector("#app-menu.open") !== null;
    if (kBrowsingSteps.includes(id)) {
      if (!browserOpen) press("#open-sample-browser-button");
    } else {
      if (browserOpen) press("#close-sample-browser-button");
      if (menuOpen !== (id === "samples")) press("#app-menu-button");
    }
  }

  function back(): void {
    if (!card || stepIndex === 0) return;
    stepIndex--;
    restoreUi(kSteps[stepIndex].id);
    enterStep();
  }

  function render(): void {
    if (!card) return;
    const step = kSteps[stepIndex];
    card.dataset.step = step.id;
    card.classList.toggle("tutorial-has-figure", step.id in kStepImages);
    document.body.classList.toggle("tutorial-select", browsingSamples());
    card.replaceChildren();
    const content = document.createElement("div");
    content.setAttribute("aria-live", "polite");
    const progress = document.createElement("div");
    progress.className = "tutorial-progress";
    progress.textContent = `${stepIndex + 1} / ${kSteps.length}`;
    const title = document.createElement("h2");
    title.id = "tutorial-title";
    title.textContent = t(`tutorial.${step.id}.title`);
    const body = document.createElement("p");
    body.textContent = t(`tutorial.${step.id}.body`);
    content.append(progress, title, body);
    const image = kStepImages[step.id];
    if (image) {
      const figure = document.createElement("div");
      figure.className = "tutorial-figure";
      const frame = document.createElement("div");
      frame.className = "tutorial-figure-frame";
      figure.append(frame);
      const picture = document.createElement("img");
      picture.width = image.width;
      picture.height = image.height;
      picture.src = image.src;
      picture.alt = t(image.alt);
      frame.append(picture);
      for (const ring of image.rings ?? []) {
        const mark = document.createElement("span");
        mark.className = "tutorial-figure-ring";
        Object.assign(mark.style, {
          left: `${ring.left}%`, top: `${ring.top}%`, width: `${ring.width}%`, height: `${ring.height}%`,
        });
        frame.append(mark);
      }
      content.append(figure);
    }
    const actions = document.createElement("div");
    actions.className = "tutorial-actions";
    function addButton(action: string, label: string, callback: () => void): void {
      const button = document.createElement("button");
      button.type = "button";
      button.dataset.tutorialAction = action;
      button.textContent = label;
      button.addEventListener("click", callback);
      actions.append(button);
    }
    addButton("skip", t("tutorial.skip"), finish);
    if (stepIndex > 0) addButton("back", t("tutorial.back"), back);
    // Watching an animation is optional, so those steps can always be passed.
    // The other actions set up state the following steps depend on.
    if (step.action !== "confirm") {
      const hint = document.createElement("span");
      hint.className = "tutorial-action-hint";
      hint.textContent = t(step.action === "watch" && watchStarted ? "tutorial.waitForPlayback" : "tutorial.waitForAction");
      actions.append(hint);
    }
    if (step.action === "confirm" || step.action === "watch") {
      addButton("next", t(stepIndex === kSteps.length - 1 ? "tutorial.done" : step.id === "intro" ? "tutorial.start" : "tutorial.next"), advance);
    }
    card.append(content, actions);
    position();
  }

  function allowed(node: EventTarget | null): boolean {
    if (!(node instanceof Node)) return false;
    if (card?.contains(node)) return true;
    if (node instanceof Element && node.closest("#close-sample-browser-button, .sample-live-fullscreen, .sample-live-preview input")) return false;
    return target()?.contains(node) ?? false;
  }

  function guard(event: Event): void {
    if (!card || restoring) return;
    if (!allowed(event.target)) {
      event.preventDefault();
      event.stopImmediatePropagation();
    } else if (event.type === "click" && !card.contains(event.target as Node) && kSteps[stepIndex].action === "watch") {
      watchStarted = true;
      render();
    } else if (event.type === "click" && !card.contains(event.target as Node) && kSteps[stepIndex].action === "click") {
      // Native dispatch can run microtasks between listeners. Use a new task
      // so the target handler has finished, even when it stops propagation.
      const index = stepIndex;
      const currentGeneration = generation;
      setTimeout(() => {
        if (!card || index !== stepIndex || currentGeneration !== generation) return;
        const id = kSteps[index].id;
        if (id === "menu" && !document.querySelector("#app-menu.open")) return;
        if (id === "samples" && !document.querySelector("#sample-browser-overlay.visible")) return;
        if (["showcase", "basic", "parts", "leaf"].includes(id) && target()?.getAttribute("aria-current") !== "true") return;
        advance();
      });
    }
  }

  function keydown(event: KeyboardEvent): void {
    if (!card) return;
    if (event.key === "Escape") {
      event.preventDefault(); event.stopImmediatePropagation(); finish();
    } else if (event.key === "Tab") {
      const candidates = [
        ...(target() ? [target()!, ...target()!.querySelectorAll<HTMLElement>('button, input, textarea, select, summary, a[href], [tabindex="0"]')] : []),
        ...card.querySelectorAll<HTMLElement>("button"),
      ].filter((element) => element.tabIndex >= 0 && !element.matches(":disabled") && element.getClientRects().length > 0 && allowed(element));
      const index = candidates.indexOf(document.activeElement as HTMLElement);
      const next = (index + (event.shiftKey ? -1 : 1) + candidates.length) % candidates.length;
      event.preventDefault(); event.stopImmediatePropagation();
      (candidates[next] ?? card).focus();
    } else {
      guard(event);
    }
  }

  function focusin(event: FocusEvent): void {
    if (card && !allowed(event.target)) card.focus();
  }
  function playbackCompleted(event: Event): void {
    if (!card || !watchStarted) return;
    const id = kSteps[stepIndex].id;
    const sampleFinished = id === "samplePreview" && event.type === "mt-sample-preview-cycle" && (event as CustomEvent<string>).detail === kTutorialSampleId;
    const mainFinished = id === "play" && event.type === "mt-playback-cycle" && event.target === target();
    if (sampleFinished || mainFinished) advance();
  }
  function sampleLoaded(event: Event): void {
    if (card && kSteps[stepIndex].id === "select" && (event as CustomEvent<string>).detail === kTutorialSampleId) advance();
  }
  function copyResult(event: Event): void {
    if (card && kSteps[stepIndex].id === "copy" && (event as CustomEvent<boolean>).detail === true) advance();
  }

  function start(): void {
    if (disposed) return;
    if (!card) previousFocus = document.activeElement as HTMLElement | null ?? undefined;
    remove();
    document.querySelector("#app-menu")?.classList.remove("open");
    document.querySelector("#app-menu-button")?.setAttribute("aria-expanded", "false");
    stepIndex = 0;
    watchStarted = false;
    shades = Array.from({ length: 4 }, () => {
      const shade = document.createElement("div");
      shade.className = "tutorial-shade";
      shade.setAttribute("aria-hidden", "true");
      return shade;
    });
    highlight = document.createElement("div");
    highlight.className = "tutorial-highlight";
    highlight.setAttribute("aria-hidden", "true");
    ring = document.createElement("div");
    ring.className = "tutorial-highlight tutorial-target-ring";
    ring.setAttribute("aria-hidden", "true");
    ring.hidden = true;
    card = document.createElement("section");
    card.className = "tutorial-card";
    card.tabIndex = -1;
    card.setAttribute("role", "dialog");
    card.setAttribute("aria-labelledby", "tutorial-title");
    document.body.append(...shades, highlight, ring, card);
    render();
    card.querySelector<HTMLButtonElement>('[data-tutorial-action="next"]')?.focus();
    trackTarget();
  }

  const guardedEvents = ["pointerdown", "mousedown", "touchstart", "click", "dblclick", "contextmenu", "wheel", "keyup"];
  guardedEvents.forEach((type) => document.addEventListener(type, guard, { capture: true, passive: false }));
  document.addEventListener("keydown", keydown, true);
  document.addEventListener("focusin", focusin, true);
  document.addEventListener("mt-tutorial-sample-loaded", sampleLoaded);
  document.addEventListener("mt-tutorial-copy-result", copyResult);
  document.addEventListener("mt-sample-preview-cycle", playbackCompleted);
  document.addEventListener("mt-playback-cycle", playbackCompleted);
  const unsubscribe = onLocaleChange(render);
  let seen = false;
  try { seen = localStorage.getItem(kStorageKey) === "true"; } catch { /* Show the guide without storage. */ }
  if (!seen) start();
  return { start, dispose() {
    disposed = true;
    remove();
    unsubscribe();
    preloadedImages.length = 0;
    document.removeEventListener("mt-sample-preview-cycle", playbackCompleted);
    document.removeEventListener("mt-playback-cycle", playbackCompleted);
    guardedEvents.forEach((type) => document.removeEventListener(type, guard, true));
    document.removeEventListener("keydown", keydown, true);
    document.removeEventListener("focusin", focusin, true);
    document.removeEventListener("mt-tutorial-sample-loaded", sampleLoaded);
    document.removeEventListener("mt-tutorial-copy-result", copyResult);
  } };
}
